// ================= BATCH 3: MONEY & PEOPLE =================
const uid=p=>(p||'x')+Math.random().toString(36).slice(2,9);
const curMonth=()=>today().slice(0,7);
const inMonth=(d,k)=>(d||'').slice(0,7)===k;
const mName=k=>MONTHS[+k.slice(5,7)-1]+' '+k.slice(0,4);
const monthEnd=k=>{const [y,m]=k.split('-').map(Number);return k+'-'+String(new Date(y,m,0).getDate()).padStart(2,'0')};
const cairoDate=ts=>new Date(ts).toLocaleDateString('en-CA',{timeZone:'Africa/Cairo'});
const cairoTime=ts=>ts?new Date(ts).toLocaleTimeString('en-GB',{timeZone:'Africa/Cairo',hour:'2-digit',minute:'2-digit'}):'—';
const isClosed=k=>(S.closedM||[]).includes(k);
const staffOf=id=>byId(S.staff,id);
const outMonth=o=>(o.outAt?cairoDate(o.outAt):o.date).slice(0,7);
const minToH=m=>{m=Math.round(m||0);return m>=60?Math.floor(m/60)+' س '+(m%60?m%60+' د':''):m+' د'};
function workDays(k){let n=0;for(let d=k+'-01';d<=monthEnd(k);d=daysAddISO(d,1))if(!isFri(d))n++;return n}
function shiftHrs(w){const t=s=>{const [h,m]=(s||'0:0').split(':').map(Number);return h*60+(m||0)};let x=(t(w.end)-t(w.start)+1440)%1440;return (x||1440)/60}
const DEF_SEASONS=[{id:'se1',name:'الكريسماس ورأس السنة',months:[12],pct:15},{id:'se2',name:'رمضان',months:[2,3],pct:25},{id:'se3',name:'عيد الفطر',months:[3],pct:10},{id:'se4',name:'عيد الأضحى',months:[5],pct:5},{id:'se5',name:'الصيف',months:[7,8],pct:-8},{id:'se6',name:'بداية الدراسة',months:[9,10],pct:5}];
const DEF_OCC=[{id:'oc1',name:'الكريسماس',date:'2026-12-25',key:'xmas'},{id:'oc2',name:'رأس السنة الميلادية',date:'2027-01-01',key:'ny'},{id:'oc3',name:'عيد الميلاد المجيد',date:'2027-01-07',key:'xmas'},{id:'oc4',name:'رمضان',date:'2027-02-08',key:'ramadan'},{id:'oc5',name:'العشر الأواخر من رمضان',date:'2027-02-27',key:'ramadan10'},{id:'oc6',name:'عيد الفطر',date:'2027-03-10',key:'eid'},{id:'oc7',name:'شم النسيم',date:'2027-05-03',key:'spring'},{id:'oc8',name:'عيد الأضحى',date:'2027-05-16',key:'eid'},{id:'oc9',name:'رأس السنة الهجرية',date:'2027-06-06',key:'hijri'},{id:'oc10',name:'المولد النبوي',date:'2027-08-15',key:'mawlid'}];
function applyDefaults(){S.settings=Object.assign({changePct:20,idleMax:10,graceMin:0,radius:100,geo:null,openingInv:0,valMult:[24,36],
 expCats:['منظفات','كهربا','مية','غاز','إيجار','نت وتليفونات','نقل وتوصيل','صيانة','تغليف بره المخزن','ضيافة','أدوات','أخرى'],fixedCats:['إيجار','كهربا','مية','غاز','نت وتليفونات']},S.settings);
 S.seasons=S.settings.seasons||JSON.parse(JSON.stringify(DEF_SEASONS));S.occasions=S.settings.occasions||DEF_OCC;
 [...new Set(S.expenses.map(e=>e.cat))].forEach(c=>{if(!S.settings.expCats.includes(c))S.settings.expCats.push(c)})}
const _loadAllBase=loadAll;loadAll=async function(){await _loadAllBase();applyDefaults()};
async function saveSettings(patch){const d=Object.assign({},S.settings,patch);delete d.__;await dbx(sb.from('settings').update({data:d,updated_at:new Date().toISOString()}).eq('id',1));await refresh()}

// ---------- payroll engine ----------
function attOf(w,d){return S.att.find(a=>a.w===w.id&&a.d===d)}
function calcRange(w,from,to){const r={from,to,days:0,present:0,leave:0,absent:0,pending:0,late:0,ot:0,base:0,absDed:0,lateDed:0,otAdd:0,comm:0,bonus:0,deduct:0,adj:[],missing:0};
 const lim=to>today()?today():to;const hrs=shiftHrs(w);
 for(let d=from;d<=lim;d=daysAddISO(d,1)){if(isFri(d)||(w.since&&d<w.since))continue;r.days++;const k=d.slice(0,7);const dayRate=w.type==='monthly'?w.salary/workDays(k):w.salary;const hr=dayRate/hrs;const a=attOf(w,d);
  const st=a?a.status:'none';
  if(st==='approved'||st==='pending'){r.present++;if(st==='pending')r.pending++;r.late+=a.late;r.ot+=a.ot;r.lateDed+=a.late/60*hr;r.otAdd+=a.ot/60*hr;r.base+=dayRate}
  else if(st==='leave'){r.leave++;r.base+=w.type==='monthly'?dayRate:0}
  else{r.absent++;if(st==='none')r.missing++;if(w.type==='monthly'){r.base+=dayRate;r.absDed+=d<today()||a?dayRate:0}}}
 if(w.courier){const c=cour(w.courier);if(c&&c.commOn)r.comm=S.orders.filter(o=>o.courier===c.id&&o.status==='delivered'&&o.outAt&&cairoDate(o.outAt)>=from&&cairoDate(o.outAt)<=to).length*c.comm}
 return r}
function adjOpen(w,toM){const paid=new Set(S.payroll.filter(p=>p.w===w.id).flatMap(p=>(p.details&&p.details.adj)||[]));return S.adjust.filter(a=>a.w===w.id&&a.m<=toM&&!paid.has(a.id))}
function grossOf(r,adj){const b=adj.filter(a=>a.kind==='bonus').reduce((s,a)=>s+a.amt,0),dd=adj.filter(a=>a.kind==='deduct').reduce((s,a)=>s+a.amt,0);return Math.max(0,r.base-r.absDed-r.lateDed+r.otAdd+r.comm+b-dd)}
function nextPeriod(w){const last=S.payroll.filter(p=>p.w===w.id).sort((a,b)=>(a.to||'')<(b.to||'')?-1:1).pop();
 if(w.type==='monthly'){let k=last&&last.m?addMonth(last.m,1):(w.since||today()).slice(0,7);if(k>curMonth())k=curMonth();return {m:k,from:k+'-01',to:monthEnd(k)}}
 const from=last&&last.to?daysAddISO(last.to,1):(w.since||today());let to=today();if(w.payMode==='weekly'){let x=from;while(new Date(x+'T12:00').getDay()!==4&&x<today())x=daysAddISO(x,1);to=x}return {m:to.slice(0,7),from,to}}
function payrollMonth(k){return S.staff.reduce((s,w)=>{if(!w.active&&!S.att.some(a=>a.w===w.id&&inMonth(a.d,k)))return s;const r=calcRange(w,k+'-01',monthEnd(k));const adj=S.adjust.filter(a=>a.w===w.id&&a.m===k);return s+grossOf(r,adj)},0)}
const advOpen=w=>S.advances.filter(a=>a.w===w.id&&a.amt-a.repaid>0.5);
const advRem=w=>advOpen(w).reduce((s,a)=>s+a.amt-a.repaid,0);

// ---------- assets ----------
function monthsDiff(a,b){const [y1,m1]=a.split('-').map(Number),[y2,m2]=b.split('-').map(Number);return (y2-y1)*12+(m2-m1)}
function depFor(a,k){if(!a.date)return 0;const i=monthsDiff(a.date.slice(0,7),k);if(i<0||i>=a.life)return 0;if(a.disposed&&k>a.disposed.slice(0,7))return 0;return (a.cost-a.salvage)/a.life}
function depAcc(a,k){const i=Math.min(a.life,Math.max(0,monthsDiff(a.date.slice(0,7),k)+1));return (a.cost-a.salvage)/a.life*i}

// ---------- P&L ----------
function monthPL(k){const c=S.closings[k];if(c&&c.status==='closed'&&c.pl&&c.pl.sales!=null)return Object.assign({},c.pl,{k,closed:true,net:c.pl.sales-c.pl.cogs-c.pl.exp-(c.pl.waste||0)});
 let sales=0,std=0;S.orders.filter(o=>billable(o)&&outMonth(o)===k).forEach(o=>{sales+=o.total;std+=o.cost});
 const rets=S.returns.filter(r=>inMonth(r.d,k));const retDed=rets.filter(r=>r.kind==='deduct').reduce((s,r)=>s+r.value,0);sales-=retDed;const retCost=rets.reduce((s,r)=>s+r.cost,0);
 const purch=S.purchases.filter(p=>inMonth(p.d,k)).reduce((s,p)=>s+purTotal(p),0);
 const prevK=addMonth(k,-1);const prev=S.closings[prevK];const openInv=prev&&prev.pl&&prev.pl.closeInv!=null?prev.pl.closeInv:(+S.settings.openingInv||0);
 const cnt=S.counts[k];const counted=!!(cnt&&cnt.status==='approved');const closeInv=counted?cnt.value:stockValue().all;
 const cogs=counted?openInv+purch-closeInv:std+retCost;
 const payroll=payrollMonth(k);const exps=S.expenses.filter(e=>inMonth(e.d,k)&&!e.acc);const otherExp=exps.reduce((s,e)=>s+e.amt,0);
 const accr=S.accruals.filter(a=>a.m===k).reduce((s,a)=>s+a.amt,0);const dep=S.assets.reduce((s,a)=>s+depFor(a,k),0);
 const byCat={};exps.forEach(e=>byCat[e.cat]=(byCat[e.cat]||0)+e.amt);S.accruals.filter(a=>a.m===k).forEach(a=>byCat[a.cat+' (مستحق)']=(byCat[a.cat+' (مستحق)']||0)+a.amt);
 const exp=payroll+otherExp+accr+dep;const [yy,mm]=k.split('-').map(Number);const dim=new Date(yy,mm,0).getDate();const frac=k===curMonth()?Math.min(1,+today().slice(8)/dim):1;
 return {k,sales,std,retCost,retDed,cogs,payroll,otherExp,accr,dep,exp,byCat,waste:0,openInv,closeInv,purch,net:sales-cogs-exp,open:true,counted,frac,varLoss:cnt?cnt.loss:0,varGain:cnt?cnt.gain:0}}
function distribute(net,reserve,k){reserve=reserve||0;k=k||curMonth();const ms=k+'-01',me_=monthEnd(k);const rows=[];let pool=net-reserve;
 S.partners.filter(p=>p.kind==='temp'&&!p.exited&&(!p.start||p.start<=me_)&&(!p.end||p.end>=ms)).forEach(t=>{let amt=0,how='';
  if(t.method==='fixedReturn'){amt=t.capital*t.rate/100;how='عائد ثابت '+t.rate+'% شهريًا من '+money(t.capital)}
  else if(t.method==='fixedShare'){amt=Math.max(0,net-reserve)*t.rate/100;how='نسبة ثابتة '+t.rate+'% من الصافي قبل التوزيع'}
  else{amt=Math.max(0,net-reserve)*t.rate/100;how='نسبة '+t.rate+'% مخصومة من نسب الشركاء بالتناسب'}
  rows.push({p:t,amt,how});pool-=amt});
 S.partners.filter(p=>p.kind==='main'&&!p.exited).forEach(p=>rows.push({p,amt:pool*p.share/100,how:p.share+'% من الباقي'}));return rows}
function monthsChart(){const ks=S.months.map(m=>m.k).concat([curMonth()]).filter((v,i,a)=>a.indexOf(v)===i).slice(-6);const data=ks.map(k=>monthPL(k));
 const W=560,H=230,pad=40,max=Math.max(1000,Math.ceil(Math.max(...data.map(d=>d.sales))/10000)*10000),bw=(W-pad-10)/data.length;const y=v=>H-22-(v/max)*(H-40);
 let g='';[0,.5,1].forEach(f=>{const v=max*f;g+=`<line x1="${pad}" x2="${W}" y1="${y(v)}" y2="${y(v)}" stroke="var(--line)"/><text x="${pad-4}" y="${y(v)+4}" text-anchor="end">${fmt(v/1000,0)}k</text>`});
 data.forEach((d,i)=>{const x=pad+8+i*bw;g+=`<rect x="${x}" y="${y(d.sales)}" width="${bw*0.42}" height="${H-22-y(d.sales)}" rx="3" fill="var(--choc)" opacity=".85"/><rect x="${x+bw*0.44}" y="${y(Math.max(0,d.net))}" width="${bw*0.42}" height="${H-22-y(Math.max(0,d.net))}" rx="3" fill="var(--accent)"/><text x="${x+bw*0.43}" y="${H-6}" text-anchor="middle">${MONTHS[+d.k.slice(5)-1]}${d.open?'*':''}</text><text x="${x+bw*0.65}" y="${y(Math.max(0,d.net))-4}" text-anchor="middle" style="fill:var(--fg);font-weight:600">${pct(d.net/(d.sales||1))}</text>`});
 return `<svg class="chart" viewBox="0 0 ${W} ${H}">${g}</svg><div class="row small muted"><span>■ <span style="color:var(--choc)">المبيعات</span></span><span>■ <span style="color:var(--accent)">صافي الربح ونسبته</span></span><span>* شهر مفتوح</span></div>`}
const monthTabs=(keys,cur,act)=>`<div class="tabs">${keys.map(x=>`<button class="tab ${x===cur?'on':''}" data-a="${act}" data-v="${x}">${mName(x)}${isClosed(x)?' 🔒':''}</button>`).join('')}</div>`;
const recentMonths=n=>{const out=[];let k=curMonth();for(let i=0;i<n;i++){out.unshift(k);k=addMonth(k,-1)}return out};

// ---------- EXPENSES ----------
V.expenses=()=>{const k=TAB.expM||curMonth();const ex=S.expenses.filter(e=>inMonth(e.d,k));const by={};ex.forEach(e=>by[e.cat]=(by[e.cat]||0)+e.amt);const tot=ex.reduce((s,e)=>s+e.amt,0);const mx=Math.max(1,...Object.values(by));const acc=S.accruals.filter(a=>a.amt-a.paid>0.5);
 return head('المصروفات','منظفات، كهربا، غاز، إيجار، صيانة، وأي بند جديد · المرتبات بتتحسب من شاشة الموظفين',`<button class="btn" data-a="newExp">+ مصروف</button>`)+monthTabs(recentMonths(6),k,'expM')+
 (acc.length?`<div class="card" style="margin-bottom:12px"><h2 class="sec-title">مستحقات لسه ما اتدفعتش ${ti('مصروفات اتحسبت على شهر مقفول ولسه ما اتدفعتش. لما تدفعها اختارها هنا علشان ما تتحسبش تاني على الشهر الجديد')}</h2><div class="list">${acc.map(a=>`<div class="li"><div class="main"><div class="t">${esc(a.cat)} · ${mName(a.m)}</div><div class="s">${esc(a.note)}${a.paid?' · اتدفع '+fmt(a.paid):''}</div></div><div class="e"><div class="b">${money(a.amt-a.paid)}</div><button class="btn sm" data-a="payAccr" data-v="${a.id}">دفع</button></div></div>`).join('')}</div></div>`:'')+
 `<div class="card"><div class="between"><h2>${mName(k)}</h2><b>${money(tot)}</b></div><div class="stack" style="margin-top:10px">${Object.entries(by).sort((a,b)=>b[1]-a[1]).map(([c,v])=>`<div><div class="between small"><span>${esc(c)}</span><span class="num">${money(v)}</span></div><div class="bar"><i style="width:${v/mx*100}%"></i></div></div>`).join('')||'<div class="empty">مفيش مصروفات في الشهر ده</div>'}</div></div>
 <div class="card" style="margin-top:12px"><div class="list">${ex.slice().reverse().map(e=>`<div class="li"><div class="main"><div class="t">${esc(e.cat)}${e.acc?' <span class="tag-mini">سداد مستحق</span>':''}</div><div class="s">${dShort(e.d)} · ${esc(e.note||'')} · ${e.t?tName(e.t):'—'}${e.by?' · '+esc(e.by):''}</div></div><div class="e"><div class="b down">${fmt(e.amt)}</div>${me().owner&&!e.courier&&!isClosed(k)?`<button class="btn ghost sm" data-a="delExp" data-v="${e.id}">حذف</button>`:''}</div></div>`).join('')}</div></div>`};
A.expM=el=>{TAB.expM=el.dataset.v;render()};
function expSheet(pre){pre=pre||{};sheet(`<h2>${pre.acc?'دفع مستحق':'مصروف جديد'}</h2><div class="fgrid"><div class="field"><label for="ex-c">البند</label><select id="ex-c" data-chg="expCat" ${pre.acc?'disabled':''}>${S.settings.expCats.map(c=>`<option ${pre.cat===c?'selected':''}>${esc(c)}</option>`).join('')}<option value="__new">بند جديد…</option></select></div><div class="field" id="ex-new-w" hidden><label for="ex-new">اسم البند الجديد</label><input id="ex-new" type="text"></div>
 <div class="field"><label for="ex-v">المبلغ</label><input id="ex-v" type="number" value="${pre.amt||''}"></div>${bdField('ex-d')}<div class="field"><label for="ex-t">من خزنة</label><select id="ex-t">${trOpts(myTre())}</select></div><div class="field full"><label for="ex-n">ملاحظة</label><input id="ex-n" type="text" value="${esc(pre.note||'')}"></div></div>
 <button class="btn block" style="margin-top:12px" data-a="expSave" data-v="${pre.acc||''}">حفظ</button>`)}
A.newExp=()=>expSheet();
A.payAccr=el=>{const a=byId(S.accruals,el.dataset.v);if(!S.settings.expCats.includes(a.cat))S.settings.expCats.push(a.cat);expSheet({acc:a.id,cat:a.cat,amt:a.amt-a.paid,note:'مستحق '+mName(a.m)})};
A.expCat=el=>{document.getElementById('ex-new-w').hidden=el.value!=='__new'};
A.expSave=async el=>{if(_busy)return;let c=val('ex-c');if(c==='__new'){c=val('ex-new').trim();if(!c){toast('اكتب اسم البند');return}}const v=num('ex-v');if(v<=0){toast('اكتب المبلغ');return}const d=bdVal('ex-d')||today();if(isClosed(d.slice(0,7))){toast('الشهر ده مقفول');return}
 _busy=true;try{if(!S.settings.expCats.includes(c))await saveSettings({expCats:S.settings.expCats.concat([c])});await rpc('add_expense',{p:{d,cat:c,amount:v,treasury_id:val('ex-t'),note:val('ex-n'),accrual_id:el.dataset.v||''}});closeSheet();await refresh();toast('اتسجل المصروف')}finally{_busy=false}};
A.delExp=async el=>{if(!confirm('حذف المصروف ورجوع المبلغ للخزنة؟'))return;await rpc('del_expense',{p_id:el.dataset.v});await refresh();toast('اتحذف ورجع المبلغ للخزنة')};

// ---------- STAFF ----------
V.staff=()=>{const tb=tabs([['list','الموظفين'],['att','الحضور والاعتماد','مراجعة الحضور اللي الموظفين سجلوه من موبايلاتهم واعتماده'],['adv','السلف'],['pay','القبض']],'list');let body='';
 const pend=S.att.filter(a=>a.status==='pending');
 if(tb.cur==='list'){body=S.staff.length?`<div class="card"><div class="list">${S.staff.map(w=>{const P=nextPeriod(w);const r=calcRange(w,P.from,P.to);const g=grossOf(r,adjOpen(w,P.m));const ar=advRem(w);return `<div class="li click" data-a="staffDetail" data-v="${w.id}"><div class="main"><div class="t">${esc(w.name)} <span class="tag-mini">${w.type==='monthly'?'شهري':'يومية'+(w.payMode==='weekly'?' · أسبوعي':' · يومي')}</span>${w.active?'':' <span class="pill">موقوف</span>'}${w.userId?' <span class="tag-mini">📍 بيسجل من موبايله</span>':''}</div><div class="s">${esc(w.job)} · ${w.type==='monthly'?'مرتب '+money(w.salary):'يومية '+money(w.salary)} · ${w.start}–${w.end}${ar?' · سلف '+money(ar):''}</div></div><div class="e"><div class="b">${money(g)}</div><div class="small muted">${w.type==='monthly'?'مستحق '+mName(P.m):'من '+dShort(P.from)}</div></div></div>`}).join('')}</div></div>`:emptyState('ضيف الموظفين بالشهري واليومية، وكل واحد بميعاد ورديته.','<button class="btn" data-a="editStaff" data-v="">+ موظف</button>')}
 else if(tb.cur==='att'){const d=TAB.attD||today();body=`${pend.length?`<div class="card" style="margin-bottom:12px"><div class="between"><h2>محتاج اعتماد (${pend.length})</h2>${can('approve')?'<button class="btn sm" data-a="attApproveAll">اعتماد الكل المكتمل</button>':''}</div><div class="list" style="margin-top:6px">${pend.slice(0,60).map(a=>attRow(a,true)).join('')}</div></div>`:''}
  <div class="card"><div class="between"><h2>يوم</h2><div class="row"><input type="date" id="att-d" value="${d}" data-chg="attDay"><button class="btn sec sm" data-a="attManual" data-v="">+ تسجيل يدوي</button></div></div><div class="list" style="margin-top:6px">${S.staff.filter(w=>w.active).map(w=>{const a=attOf(w,d);return a?attRow(a,false):`<div class="li"><div class="main"><div class="t">${esc(w.name)}</div><div class="s">${isFri(d)?'جمعة — إجازة':'مفيش تسجيل'}</div></div>${isFri(d)?'':`<div class="row"><button class="btn ghost sm" data-a="attManual" data-v="${w.id}" data-d="${d}">تسجيل</button><button class="btn ghost sm" data-a="attLeave" data-v="${w.id}" data-d="${d}">إجازة</button></div>`}</div>`}).join('')}</div></div>`}
 else if(tb.cur==='adv'){body=`<div class="card"><div class="list">${S.advances.slice().reverse().map(a=>`<div class="li"><div class="main"><div class="t">${esc(staffOf(a.w)?.name||'')} · ${money(a.amt)}</div><div class="s">${dShort(a.d)} · ${a.mode==='once'?'تتخصم مرة واحدة':'قسط '+money(a.inst)}${a.note?' · '+esc(a.note):''} · ${tName(a.t)}</div></div><div class="e"><div class="b ${a.amt-a.repaid>0.5?'down':'up'}">${a.amt-a.repaid>0.5?'باقي '+fmt(a.amt-a.repaid):'اتسددت'}</div></div></div>`).join('')||'<div class="empty">مفيش سلف</div>'}</div></div>`}
 else{body=`<div class="card"><div class="list">${S.payroll.slice().reverse().map(p=>`<div class="li"><div class="main"><div class="t">${esc(staffOf(p.w)?.name||'')}</div><div class="s">${dShort(p.d)} · ${p.from?dShort(p.from)+' → '+dShort(p.to):''} · ${tName(p.t)}${p.adv?' · خصم سلف '+fmt(p.adv):''}</div></div><div class="e b">${money(p.net)}</div></div>`).join('')||'<div class="empty">لسه مفيش قبض</div>'}</div></div>`}
 const due=S.staff.filter(w=>w.active).reduce((s,w)=>{const P=nextPeriod(w);return s+grossOf(calcRange(w,P.from,P.to),adjOpen(w,P.m))},0);
 return head('الموظفين والمرتبات','شهري ويومية · الحضور بالموقع من جوه المصنع · الغياب والتأخير والأوفر تايم بسعر الساعة · السلف مرة واحدة أو أقساط','<button class="btn" data-a="editStaff" data-v="">+ موظف</button><button class="btn sec" data-a="newAdv">+ سلفة</button>')+
 `<div class="grid3" style="margin-bottom:12px">${kpi('المستحق للموظفين دلوقتي',mv(due),'قبل خصم السلف')}${kpi('سلف لسه ما اتسددتش',mv(S.staff.reduce((s,w)=>s+advRem(w),0)))}${kpi('حضور مستني اعتماد',`${pend.length}`,'',{cls:pend.length?'down':''})}</div>`+tb.html+body};
function attRow(a,showDate){const w=staffOf(a.w);const S_={pending:['مستني','warn'],approved:['معتمد','ok'],rejected:['مرفوض','bad'],leave:['إجازة','acc'],absent:['غياب','bad']}[a.status]||['',''];
 return `<div class="li"><div class="main"><div class="t">${esc(w?.name||'')} <span class="pill ${S_[1]}">${S_[0]}</span>${a.src==='manual'?' <span class="tag-mini">يدوي</span>':''}</div><div class="s">${showDate?dShort(a.d)+' · ':''}حضور ${cairoTime(a.in)}${a.inDist!=null?' ('+fmt(a.inDist)+'م)':''} · انصراف ${cairoTime(a.out)}${a.status==='approved'?(a.late?' · تأخير '+minToH(a.late):'')+(a.ot?' · أوفر تايم '+minToH(a.ot):''):''}${a.note?' · '+esc(a.note):''}</div></div>
 <div class="row">${a.status==='pending'&&can('approve')?`<button class="btn sm" data-a="attOk" data-v="${a.id}" ${a.out?'':'disabled title="لسه ما سجلش انصراف"'}>اعتماد</button><button class="btn ghost sm" data-a="attNo" data-v="${a.id}">رفض</button>`:''}<button class="btn ghost sm" data-a="attManual" data-v="${a.w}" data-d="${a.d}">تعديل</button></div></div>`}
A.attDay=el=>{TAB.attD=el.value;render()};
A.attOk=async el=>{await rpc('att_approve',{p:{ids:[el.dataset.v],status:'approved'}});await refresh();toast('اتعتمد')};
A.attNo=async el=>{await rpc('att_approve',{p:{ids:[el.dataset.v],status:'rejected'}});await refresh();toast('اترفض، اليوم هيتحسب غياب')};
A.attApproveAll=async()=>{const ids=S.att.filter(a=>a.status==='pending'&&a.out).map(a=>a.id);if(!ids.length){toast('مفيش حضور مكتمل (حضور وانصراف)');return}const n=await rpc('att_approve',{p:{ids,status:'approved'}});await refresh();toast('اتعتمد '+n)};
A.attLeave=async el=>{await rpc('att_manual',{p:{staff_id:el.dataset.v,d:el.dataset.d,status:'leave',note:'إجازة'}});await refresh();toast('اتسجلت إجازة مدفوعة')};
A.attManual=el=>{const w0=el.dataset.v?staffOf(el.dataset.v):null;const d=el.dataset.d||TAB.attD||today();const a=w0?attOf(w0,d):null;
 sheet(`<h2>تسجيل حضور يدوي</h2><p class="sub">للي معندوش موبايل أو نسي يسجل. ${can('approve')?'بيتعتمد على طول.':'هيستنى اعتماد المالك.'}</p><div class="fgrid"><div class="field"><label for="am-w">الموظف</label><select id="am-w">${S.staff.filter(w=>w.active).map(w=>`<option value="${w.id}" ${w0&&w0.id===w.id?'selected':''}>${esc(w.name)} (${w.start}–${w.end})</option>`).join('')}</select></div><div class="field"><label for="am-d">اليوم</label><input id="am-d" type="date" value="${d}"></div>
 <div class="field"><label for="am-st">الحالة</label><select id="am-st"><option value="approved">حضر</option><option value="leave" ${a&&a.status==='leave'?'selected':''}>إجازة مدفوعة</option><option value="absent" ${a&&a.status==='absent'?'selected':''}>غياب</option></select></div><div class="field"></div>
 <div class="field"><label for="am-in">ساعة الحضور</label><input id="am-in" type="time" value="${a&&a.in?cairoTime(a.in):(w0?w0.start:'16:00')}"></div><div class="field"><label for="am-out">ساعة الانصراف</label><input id="am-out" type="time" value="${a&&a.out?cairoTime(a.out):(w0?w0.end:'00:00')}"></div><div class="field full"><label for="am-n">ملاحظة</label><input id="am-n" type="text" value="${esc(a?a.note:'')}"></div></div>
 <button class="btn block" style="margin-top:12px" data-a="attManualSave">حفظ</button>`)};
A.attManualSave=async()=>{const st=val('am-st');const d=val('am-d');if(isFri(d)&&st!=='approved'){toast('الجمعة إجازة أصلًا');return}await rpc('att_manual',{p:{staff_id:val('am-w'),d,status:st,in:st==='approved'?val('am-in'):'',out:st==='approved'?val('am-out'):'',note:val('am-n')}});closeSheet();await refresh();toast('اتسجل')};
A.editStaff=el=>{const w=el.dataset.v?staffOf(el.dataset.v):{id:'',name:'',job:'',phone:'',type:'monthly',salary:0,payMode:'monthly',start:'16:00',end:'00:00',userId:null,courier:null,since:today(),active:true};
 sheet(`<h2>${w.id?'تعديل موظف':'موظف جديد'}</h2><div class="fgrid"><div class="field"><label for="sf-n">الاسم</label><input id="sf-n" type="text" value="${esc(w.name)}"></div><div class="field"><label for="sf-j">الوظيفة</label><input id="sf-j" type="text" value="${esc(w.job)}" placeholder="شيف، مساعد، تغليف، نظافة..."></div>
 <div class="field"><label for="sf-ph">الموبايل</label><input id="sf-ph" type="tel" value="${esc(w.phone)}"></div><div class="field"><label for="sf-t">النوع</label><select id="sf-t" data-chg="sfType"><option value="monthly" ${w.type==='monthly'?'selected':''}>مرتب شهري</option><option value="daily" ${w.type==='daily'?'selected':''}>يومية</option></select></div>
 <div class="field"><label for="sf-s">${w.type==='monthly'?'المرتب الشهري':'اليومية'}</label><input id="sf-s" type="number" value="${w.salary||''}"></div><div class="field" id="sf-pm-w" ${w.type==='daily'?'':'hidden'}><label for="sf-pm">بيقبض</label><select id="sf-pm"><option value="daily" ${w.payMode==='daily'?'selected':''}>كل يوم</option><option value="weekly" ${w.payMode==='weekly'?'selected':''}>آخر الأسبوع (الخميس)</option></select></div>
 <div class="field"><label for="sf-a">ميعاد الحضور</label><input id="sf-a" type="time" value="${w.start}"></div><div class="field"><label for="sf-b">ميعاد الانصراف</label><input id="sf-b" type="time" value="${w.end}"></div>
 <div class="field"><label for="sf-since">بداية الشغل</label><input id="sf-since" type="date" value="${w.since||today()}"></div><div class="field"><label for="sf-u">بيسجل حضوره من موبايله بحساب ${ti('اعمله حساب من «المستخدمين والصلاحيات» من غير شاشات، واربطه هنا. هيشوف بس شاشة «حضوري ومرتبي»')}</label><select id="sf-u"><option value="">— لأ —</option>${S.users.filter(u=>!u.owner).map(u=>`<option value="${u.id}" ${w.userId===u.id?'selected':''}>${esc(u.name)}</option>`).join('')}</select></div>
 <div class="field"><label for="sf-c">مندوب؟ (للعمولة)</label><select id="sf-c"><option value="">— لأ —</option>${S.couriers.filter(c=>c.kind==='main').map(c=>`<option value="${c.id}" ${w.courier===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div>
 ${w.id?`<div class="field" style="justify-content:flex-end"><label class="small"><input type="checkbox" id="sf-act" ${w.active?'checked':''}> شغال</label></div>`:''}</div>
 <p class="small muted" style="margin-top:8px">سعر الساعة = ${w.type==='monthly'?'المرتب ÷ أيام الشغل في الشهر (من غير الجمع) ÷ ساعات الوردية':'اليومية ÷ ساعات الوردية'}. الغياب والتأخير بيتخصموا، والأوفر تايم بيتضاف بنفس سعر الساعة.</p>
 <button class="btn block" style="margin-top:12px" data-a="saveStaff" data-v="${w.id}">حفظ</button>`)};
A.sfType=el=>{document.getElementById('sf-pm-w').hidden=el.value!=='daily';document.querySelector('label[for=sf-s]').textContent=el.value==='daily'?'اليومية':'المرتب الشهري'};
A.saveStaff=async el=>{const n=val('sf-n').trim();if(!n){toast('اكتب الاسم');return}const t=val('sf-t');const act=document.getElementById('sf-act');
 await dbx(sb.from('staff').upsert({id:el.dataset.v||uuid(),name:n,job:val('sf-j'),phone:val('sf-ph'),type:t,salary:num('sf-s'),pay_mode:t==='monthly'?'monthly':val('sf-pm'),shift_start:val('sf-a')||'16:00',shift_end:val('sf-b')||'00:00',start_date:val('sf-since')||today(),user_id:val('sf-u')||null,courier_id:val('sf-c')||null,active:act?act.checked:true}));closeSheet();await refresh();toast('اتحفظ الموظف')};
A.staffDetail=el=>{const w=staffOf(el.dataset.v);const P=TAB.payP&&TAB.payP.w===w.id?TAB.payP:Object.assign({w:w.id},nextPeriod(w));const r=calcRange(w,P.from,P.to);const adj=adjOpen(w,P.m);const g=grossOf(r,adj);const hr=(w.type==='monthly'?w.salary/workDays(P.m):w.salary)/shiftHrs(w);
 const advs=advOpen(w);const sug=a=>a.mode==='once'?a.amt-a.repaid:Math.min(a.inst,a.amt-a.repaid);
 sheet(`<div class="between"><h2>${esc(w.name)}</h2><button class="btn sec sm" data-a="editStaff" data-v="${w.id}">تعديل</button></div><p class="sub">${w.type==='monthly'?'مرتب '+money(w.salary):'يومية '+money(w.salary)} · وردية ${w.start}–${w.end} (${fmt(shiftHrs(w),1)} ساعة) · الساعة ${money(hr)}</p>
 <div class="fgrid"><div class="field"><label for="pp-f">من</label><input id="pp-f" type="date" value="${P.from}" data-chg="payPer" data-v="${w.id}"></div><div class="field"><label for="pp-t">إلى</label><input id="pp-t" type="date" value="${P.to}" data-chg="payPer" data-v="${w.id}"></div></div>
 <div class="tbl-wrap" style="margin-top:10px"><table><tr><td>أيام شغل في الفترة (لحد النهارده)</td><td class="n">${r.days}</td></tr><tr><td>حضور${r.pending?' ('+r.pending+' مستني اعتماد)':''}</td><td class="n">${r.present}</td></tr>${r.leave?`<tr><td>إجازة مدفوعة</td><td class="n">${r.leave}</td></tr>`:''}<tr><td>غياب${r.missing?' ('+r.missing+' من غير تسجيل)':''}</td><td class="n ${r.absent?'down':''}">${r.absent}</td></tr>
 <tr><td>${w.type==='monthly'?'المرتب عن الفترة':'اليوميات'}</td><td class="n">${fmt(r.base)}</td></tr>${r.absDed?`<tr><td>خصم غياب</td><td class="n down">-${fmt(r.absDed)}</td></tr>`:''}${r.lateDed?`<tr><td>خصم تأخير وانصراف بدري (${minToH(r.late)})</td><td class="n down">-${fmt(r.lateDed)}</td></tr>`:''}${r.otAdd?`<tr><td>أوفر تايم (${minToH(r.ot)})</td><td class="n up">+${fmt(r.otAdd)}</td></tr>`:''}${r.comm?`<tr><td>عمولة توصيل</td><td class="n up">+${fmt(r.comm)}</td></tr>`:''}
 ${adj.map(a=>`<tr><td>${a.kind==='bonus'?'مكافأة':'خصم'} ${mName(a.m)} — ${esc(a.note)}</td><td class="n ${a.kind==='bonus'?'up':'down'}">${a.kind==='bonus'?'+':'-'}${fmt(a.amt)}</td></tr>`).join('')}<tr class="tot"><td>المستحق</td><td class="n">${fmt(g)}</td></tr></table></div>
 <button class="btn ghost sm" style="margin-top:6px" data-a="newAdj" data-v="${w.id}">+ مكافأة أو خصم</button>
 ${advs.length?`<h3 style="margin-top:12px">خصم السلف</h3>${advs.map(a=>`<div class="row" style="flex-wrap:nowrap;margin-bottom:6px"><span class="small" style="flex:1">${dShort(a.d)} · باقي ${fmt(a.amt-a.repaid)} · ${a.mode==='once'?'مرة واحدة':'قسط '+fmt(a.inst)}</span><input type="number" class="inp-sm" id="pa-${a.id}" value="${Math.min(sug(a),g)}" style="width:96px"></div>`).join('')}`:''}
 <div class="fgrid" style="margin-top:10px"><div class="field"><label for="pp-tr">القبض من</label><select id="pp-tr">${trOpts(myTre())}</select></div><div class="field"><label for="pp-n">ملاحظة</label><input id="pp-n" type="text"></div>${bdField('pp-d','تاريخ القبض')}</div>
 <button class="btn block" style="margin-top:12px" data-a="payStaff" data-v="${w.id}">صرف القبض</button>
 <details style="margin-top:12px"><summary class="small" style="color:var(--accent)">آخر قبض وسلف</summary><div class="list">${S.payroll.filter(p=>p.w===w.id).slice(-6).reverse().map(p=>`<div class="li"><div class="main"><div class="t small">${dShort(p.d)} · ${p.from?dShort(p.from)+' → '+dShort(p.to):''}</div><div class="s">إجمالي ${fmt(p.gross)} · سلف ${fmt(p.adv)}</div></div><div class="e b">${fmt(p.net)}</div></div>`).join('')}${S.advances.filter(a=>a.w===w.id).slice(-6).reverse().map(a=>`<div class="li"><div class="main"><div class="t small">سلفة ${dShort(a.d)}</div><div class="s">${a.mode==='once'?'مرة واحدة':'قسط '+fmt(a.inst)}</div></div><div class="e">${fmt(a.amt)} / باقي ${fmt(a.amt-a.repaid)}</div></div>`).join('')}</div></details>`)};
A.payPer=el=>{const w=staffOf(el.dataset.v);TAB.payP={w:w.id,from:val('pp-f'),to:val('pp-t'),m:val('pp-t').slice(0,7)};A.staffDetail({dataset:{v:w.id}})};
A.payStaff=async el=>{if(_busy)return;const w=staffOf(el.dataset.v);const from=val('pp-f'),to=val('pp-t');const m=to.slice(0,7);const r=calcRange(w,from,to);const adj=adjOpen(w,m);const g=+grossOf(r,adj).toFixed(2);
 const adv=advOpen(w).map(a=>({id:a.id,amt:num('pa-'+a.id)})).filter(x=>x.amt>0);const ded=adv.reduce((s,x)=>s+x.amt,0);if(ded>g+0.01){toast('خصم السلف أكبر من المستحق');return}
 if(r.pending&&!confirm('فيه '+r.pending+' يوم حضور لسه ما اتعتمدش. تكمل؟'))return;
 _busy=true;try{await rpc('pay_staff',{p:{staff_id:w.id,month:m,from,to,gross:g,adv,treasury_id:val('pp-tr'),note:val('pp-n'),d:bdVal('pp-d'),details:{present:r.present,absent:r.absent,leave:r.leave,late:r.late,ot:r.ot,base:+r.base.toFixed(2),absDed:+r.absDed.toFixed(2),lateDed:+r.lateDed.toFixed(2),otAdd:+r.otAdd.toFixed(2),comm:r.comm,adj:adj.map(a=>a.id)}}});TAB.payP=null;closeSheet();await refresh();toast('اتصرف '+money(g-ded)+' لـ '+w.name)}finally{_busy=false}};
A.newAdj=el=>{const w=staffOf(el.dataset.v);sheet(`<h2>مكافأة أو خصم — ${esc(w.name)}</h2><div class="fgrid"><div class="field"><label for="aj-k">النوع</label><select id="aj-k"><option value="bonus">مكافأة</option><option value="deduct">خصم (جزاء)</option></select></div><div class="field"><label for="aj-m">على شهر</label><input id="aj-m" type="month" value="${curMonth()}"></div><div class="field"><label for="aj-v">المبلغ</label><input id="aj-v" type="number"></div><div class="field"><label for="aj-n">السبب</label><input id="aj-n" type="text"></div></div><button class="btn block" style="margin-top:12px" data-a="adjSave" data-v="${w.id}">حفظ</button>`)};
A.adjSave=async el=>{const v=num('aj-v');if(v<=0||!val('aj-n').trim()){toast('اكتب المبلغ والسبب');return}await dbx(sb.from('staff_adjust').insert({staff_id:el.dataset.v,month:val('aj-m'),kind:val('aj-k'),amount:v,note:val('aj-n')}));closeSheet();await refresh();toast('اتسجل')};
A.newAdv=()=>{if(!S.staff.length){toast('ضيف موظفين الأول');return}sheet(`<h2>سلفة</h2><div class="fgrid"><div class="field full"><label for="ad-w">الموظف</label><select id="ad-w">${S.staff.filter(w=>w.active).map(w=>`<option value="${w.id}">${esc(w.name)}${advRem(w)?' — عليه '+money(advRem(w)):''}</option>`).join('')}</select></div><div class="field"><label for="ad-v">المبلغ</label><input id="ad-v" type="number"></div><div class="field"><label for="ad-t">من خزنة</label><select id="ad-t">${trOpts(myTre())}</select></div>
 <div class="field full"><label>الخصم</label><div class="seg"><button class="on" data-a="advMode" data-v="once" id="adm-once">مرة واحدة من أول قبض</button><button data-a="advMode" data-v="inst" id="adm-inst">أقساط</button></div></div><div class="field" id="ad-i-w" hidden><label for="ad-i">قيمة القسط</label><input id="ad-i" type="number"></div><div class="field full"><label for="ad-n">ملاحظة</label><input id="ad-n" type="text"></div>${bdField('ad-d')}</div><button class="btn block" style="margin-top:12px" data-a="advSave">صرف السلفة</button>`)};
A.advMode=el=>{['once','inst'].forEach(m=>document.getElementById('adm-'+m).classList.toggle('on',m===el.dataset.v));document.getElementById('ad-i-w').hidden=el.dataset.v!=='inst'};
A.advSave=async()=>{if(_busy)return;const v=num('ad-v');if(v<=0){toast('اكتب المبلغ');return}const inst=document.getElementById('adm-inst').classList.contains('on');if(inst&&num('ad-i')<=0){toast('اكتب قيمة القسط');return}
 _busy=true;try{await rpc('give_advance',{p:{staff_id:val('ad-w'),amount:v,treasury_id:val('ad-t'),mode:inst?'inst':'once',inst_amount:inst?num('ad-i'):0,note:val('ad-n'),d:bdVal('ad-d')}});closeSheet();await refresh();toast('اتصرفت السلفة'+(inst?' على '+Math.ceil(v/num('ad-i'))+' قسط':''))}finally{_busy=false}};

// ---------- MY ATTENDANCE (staff self) ----------
V.me=()=>{const w=S.myStaff;if(!w)return head('حضوري ومرتبي')+emptyState('حسابك مش مربوط بموظف. المالك يربطه من «الموظفين والمرتبات».','');const d=today();const a=S.att.find(x=>x.w===w.id&&x.d===d)||S.att.find(x=>x.w===w.id&&x.in&&!x.out&&(Date.now()-new Date(x.in))<18*3600e3);
 const k=curMonth();const r=calcRange(w,k+'-01',monthEnd(k));const ar=advRem(w);
 return head('حضوري ومرتبي','سجّل حضورك وانصرافك وإنت جوه المصنع')+`<div class="card" style="text-align:center;padding:24px"><div class="small muted">ورديتك ${w.start} – ${w.end}</div>
 <div style="font-size:42px;font-family:var(--f-mono);margin:10px 0" id="me-clock">${cairoTime(new Date())}</div>
 ${a&&a.in?`<div class="small">حضرت ${cairoTime(a.in)}${a.out?' · مشيت '+cairoTime(a.out):''} <span class="pill ${a.status==='approved'?'ok':'warn'}">${a.status==='approved'?'معتمد':'مستني اعتماد'}</span></div>`:''}
 <div class="row" style="justify-content:center;margin-top:14px">${!a||!a.in?'<button class="btn" style="font-size:18px;padding:14px 34px" data-a="checkIn" data-v="in">📍 حضرت</button>':!a.out?'<button class="btn acc" style="font-size:18px;padding:14px 34px" data-a="checkIn" data-v="out">📍 مشيت</button>':'<span class="pill ok">خلصت النهارده</span>'}</div>
 <p class="small muted" style="margin-top:10px">لازم تسمح للموبايل بتحديد الموقع، وتكون جوه المصنع.</p></div>
 <div class="grid3" style="margin-top:12px">${kpi('أيام حضور الشهر',`${r.present}`,r.pending?r.pending+' مستني اعتماد':'')}${kpi('تأخير',minToH(r.late))}${kpi('أوفر تايم',minToH(r.ot))}</div>
 ${ar?`<div class="kpi" style="margin-top:12px"><div class="l">سلف عليك</div><div class="v down">${money(ar)}</div></div>`:''}
 <div class="card" style="margin-top:12px"><h2>آخر أيام</h2><div class="list">${S.att.filter(x=>x.w===w.id).slice(0,14).map(x=>`<div class="li"><div class="main"><div class="t small">${dShort(x.d)}</div><div class="s">${cairoTime(x.in)} → ${cairoTime(x.out)}${x.late?' · تأخير '+minToH(x.late):''}${x.ot?' · أوفر '+minToH(x.ot):''}</div></div><span class="pill ${x.status==='approved'?'ok':x.status==='pending'?'warn':''}">${{approved:'معتمد',pending:'مستني',rejected:'مرفوض',leave:'إجازة',absent:'غياب'}[x.status]}</span></div>`).join('')||'<div class="empty">لسه</div>'}</div></div>`};
A.checkIn=el=>{if(!navigator.geolocation){toast('الموبايل ده مفيهوش تحديد موقع');return}toast('بيحدد موقعك...');const act=el.dataset.v;
 navigator.geolocation.getCurrentPosition(async pos=>{try{const r=await rpc('att_check',{p:{action:act,lat:pos.coords.latitude,lng:pos.coords.longitude,acc:pos.coords.accuracy}});await refresh();toast(act==='in'?'اتسجل حضورك ✓':'اتسجل انصرافك ✓')}catch(e){}},
  err=>toast(err.code===1?'لازم تسمح بتحديد الموقع من إعدادات المتصفح':'مش قادر يحدد الموقع، جرّب تاني بره شوية أو شغّل الـ GPS'),{enableHighAccuracy:true,timeout:20000,maximumAge:0})};

// ---------- CAPITAL & ASSETS ----------
V.capital=()=>{if(!can('capital'))return head('رأس المال والتقييم')+`<div class="lock">🔒 رأس المال والتقييم للمالك بس (من الصلاحيات)</div>`;const k=curMonth();
 const fixed=S.assets.filter(a=>!a.disposed).map(a=>{const d=depAcc(a,k);return {...a,depd:d,book:a.cost-d}});const fixedBook=fixed.reduce((s,a)=>s+a.book,0);
 const sv=stockValue();const cash=S.treasuries.reduce((s,t)=>s+t.bal,0);const recv=S.customers.reduce((s,c)=>s+custLedger(c.id).bal,0);const pay=S.suppliers.reduce((s,x)=>s+supLedger(x.id).bal,0);const cust_=S.couriers.reduce((s,c)=>s+custodyBal(c.id),0);
 const partnerDue=S.partners.reduce((s,p)=>s+p.acct.reduce((a,e)=>a+e.amt,0),0);const accr=S.accruals.reduce((s,a)=>s+a.amt-a.paid,0);
 const assets=fixedBook+sv.all+cash+recv+cust_;const liab=pay+Math.max(0,partnerDue)+accr;const equity=assets-liab;const capIn=S.partners.filter(p=>!p.exited).reduce((s,p)=>s+p.capital,0);
 const parts=[['الأصول الثابتة (بعد الإهلاك)',fixedBook,'var(--choc)'],['المخزون',sv.all,'var(--caramel)'],['النقدية في الخزن',cash,'var(--ok)'],['مع المناديب',cust_,'var(--warn)'],['لينا عند العملاء',recv,'var(--accent)']];
 let a0=0;const R=60,C=2*Math.PI*R;const donut=assets>0?parts.map(([l,v,c])=>{const f=v/assets;const s=`<circle r="${R}" cx="80" cy="80" fill="none" stroke="${c}" stroke-width="26" stroke-dasharray="${f*C} ${C}" stroke-dashoffset="${-a0*C}" transform="rotate(-90 80 80)"/>`;a0+=f;return s}).join(''):'';
 const last3=S.months.slice(-3);const avgNet=last3.length?last3.reduce((s,m)=>s+(m.sales-m.cogs-m.exp-(m.waste||0)),0)/last3.length:null;const mult=S.settings.valMult||[24,36];
 return head('رأس المال والتقييم','كل قرش في المكان: فين، وقيمته الدفترية دلوقتي','<button class="btn" data-a="newAsset">+ أصل</button>')+
 `<div class="card"><div class="row" style="flex-wrap:wrap;gap:16px"><svg viewBox="0 0 160 160" width="150" height="150" style="flex:none"><circle r="${R}" cx="80" cy="80" fill="none" stroke="var(--line)" stroke-width="26"/>${donut}<text x="80" y="76" text-anchor="middle" style="fill:var(--muted);font-size:11px">إجمالي الأصول</text><text x="80" y="94" text-anchor="middle" style="fill:var(--fg);font-size:15px;font-weight:700">${fmt(assets/1000,1)}k</text></svg>
 <div class="stack" style="flex:1;min-width:180px;gap:6px">${parts.map(([l,v,c])=>`<div class="between small"><span><span style="color:${c}">■</span> ${l}</span><span class="num">${money(v)} · ${pct(v/(assets||1))}</span></div>`).join('')}</div></div></div>
 <div class="grid3" style="margin-top:12px">${kpi('علينا (موردين + شركاء + مستحقات)',`<span class="down">${money(liab)}</span>`)}${kpi('صافي حقوق الملكية',money(equity))}${kpi('رأس المال المدفوع',money(capIn),capIn?`<span class="${equity>=capIn?'up':'down'}">${equity>=capIn?'+':''}${pct((equity-capIn)/capIn)}</span>`:'')}</div>
 <div class="card" style="margin-top:12px"><div class="between"><h2>الأصول الثابتة</h2><button class="btn sec sm" data-a="newAsset">+ أصل</button></div><div class="tbl-wrap" style="margin-top:8px"><table><tr><th>الأصل</th><th class="n">التكلفة</th><th class="n">إهلاك شهري</th><th class="n">مجمع الإهلاك</th><th class="n">القيمة الحالية</th><th class="n">صيانة</th></tr>${fixed.map(a=>`<tr class="click" data-a="assetDetail" data-v="${a.id}" style="cursor:pointer"><td>${esc(a.name)}${a.partner?' <span class="tag-mini">دفعه '+esc(byId(S.partners,a.partner)?.name||'')+'</span>':''}<div class="small muted">${dShort(a.date)} ${a.date.slice(0,4)} · ${a.life} شهر</div></td><td class="n">${fmt(a.cost)}</td><td class="n">${fmt(depFor(a,k))}</td><td class="n">${fmt(a.depd)}</td><td class="n b">${fmt(a.book)}</td><td class="n">${a.maint.length?fmt(a.maint.reduce((s,m)=>s+m.cost,0)):'—'}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">ضيف المعدات: الفرن، الثلاجات، الخلاطات، العربية...</td></tr>'}${fixed.length?`<tr class="tot"><td>الإجمالي</td><td class="n">${fmt(fixed.reduce((s,a)=>s+a.cost,0))}</td><td class="n">${fmt(fixed.reduce((s,a)=>s+depFor(a,k),0))}</td><td class="n">${fmt(fixed.reduce((s,a)=>s+a.depd,0))}</td><td class="n">${fmt(fixedBook)}</td><td></td></tr>`:''}</table></div></div>
 <div class="card" style="margin-top:12px"><h2>التقييم</h2><p class="sub">قيمة المكان كنشاط شغال (تقدير يساعدك في القرار، مش تقييم رسمي)</p><div class="tbl-wrap"><table><tr><td>صافي الأصول الدفترية</td><td class="n">${money(equity)}</td></tr>
 ${avgNet==null?'<tr><td colspan="2" class="muted">التقييم بالأرباح هيظهر بعد أول شهر مقفول</td></tr>':`<tr><td>متوسط صافي الربح الشهري (آخر ${last3.length} شهور مقفولة)</td><td class="n">${money(avgNet)}</td></tr>${mult.map(x=>`<tr><td>قيمة بمضاعف ربح ${x} شهر</td><td class="n b">${money(avgNet*x)}</td></tr>`).join('')}`}</table></div>
 <p class="note" style="margin-top:8px">المضاعفات بتتغير من الإعدادات. التقييم الفعلي بيعتمد على العقود والعملاء والاسم التجاري.</p></div>`};
A.newAsset=()=>sheet(`<h2>أصل جديد</h2><div class="fgrid"><div class="field full"><label for="as-n">الاسم</label><input id="as-n" type="text" placeholder="فرن، ثلاجة، خلاط، عربية..."></div><div class="field"><label for="as-c">التكلفة</label><input id="as-c" type="number"></div><div class="field"><label for="as-dt">تاريخ الشراء</label><input id="as-dt" type="date" value="${today()}"></div>
 <div class="field"><label for="as-l">العمر (شهور)</label><input id="as-l" type="number" value="60"></div><div class="field"><label for="as-sv">قيمة الخردة في الآخر</label><input id="as-sv" type="number" value="0"></div>
 <div class="field full"><label for="as-src">اتدفع منين</label><select id="as-src" data-chg="asSrc"><option value="">موجود قبل السيستم (من غير حركة فلوس)</option>${S.treasuries.map(t=>`<option value="t:${t.id}">خزنة ${t.holder} — ${t.method}</option>`).join('')}${S.partners.filter(p=>!p.exited).map(p=>`<option value="p:${p.id}">دفعه الشريك ${esc(p.name)} (دين له)</option>`).join('')}</select></div><div class="field" id="as-i-w" hidden><label for="as-i">يترد له على كام شهر</label><input id="as-i" type="number" value="0"></div></div>
 <p class="small muted" style="margin-top:6px">الإهلاك الشهري = (التكلفة − الخردة) ÷ عدد الشهور، وبيدخل مصروف في ربح كل شهر.</p><button class="btn block" style="margin-top:12px" data-a="assetSave">إضافة</button>`);
A.asSrc=el=>{document.getElementById('as-i-w').hidden=!el.value.startsWith('p:')};
A.assetSave=async()=>{const n=val('as-n').trim(),c=num('as-c');if(!n||c<=0){toast('اكتب الاسم والتكلفة');return}const [k,id]=(val('as-src')||':').split(':');
 await rpc('add_asset',{p:{name:n,cost:c,d:val('as-dt'),life_months:Math.max(1,num('as-l')),salvage:num('as-sv'),treasury_id:k==='t'?id:'',partner_id:k==='p'?id:'',inst:k==='p'?num('as-i'):0}});closeSheet();await refresh();toast('اتضاف الأصل')};
A.assetDetail=el=>{const a=byId(S.assets,el.dataset.v);sheet(`<h2>${esc(a.name)}</h2><p class="sub">${money(a.cost)} · ${dShort(a.date)} ${a.date.slice(0,4)} · ${a.life} شهر · القيمة الحالية ${money(a.cost-depAcc(a,curMonth()))}</p>
 <h3>الصيانة</h3><div class="list">${a.maint.map(m=>`<div class="li"><div class="main"><div class="t small">${dShort(m.d)} ${m.d.slice(0,4)}</div><div class="s">${esc(m.note)}</div></div><div class="e b">${fmt(m.cost)}</div></div>`).join('')||'<div class="empty">مفيش صيانة متسجلة</div>'}</div>
 <div class="fgrid" style="margin-top:12px"><div class="field"><label for="mt-c">تكلفة الصيانة</label><input id="mt-c" type="number"></div><div class="field"><label for="mt-d">التاريخ</label><input id="mt-d" type="date" value="${today()}"></div><div class="field"><label for="mt-t">من خزنة</label><select id="mt-t">${trOpts(myTre())}</select></div><div class="field"><label for="mt-n">إيه اللي اتعمل</label><input id="mt-n" type="text"></div></div>
 <button class="btn block" style="margin-top:10px" data-a="maintSave" data-v="${a.id}">تسجيل صيانة (بتتسجل مصروف «صيانة»)</button>
 <div class="row" style="margin-top:10px"><button class="btn ghost sm" data-a="assetEdit" data-v="${a.id}">تعديل العمر أو الخردة</button>${a.disposed?'':`<button class="btn ghost sm" data-a="assetDispose" data-v="${a.id}">استبعاد (اتباع أو باظ)</button>`}</div>`)};
A.maintSave=async el=>{const c=num('mt-c');if(c<=0){toast('اكتب التكلفة');return}await rpc('asset_maint_add',{p:{asset_id:el.dataset.v,cost:c,d:val('mt-d'),treasury_id:val('mt-t'),note:val('mt-n')}});closeSheet();await refresh();toast('اتسجلت الصيانة')};
A.assetEdit=el=>{const a=byId(S.assets,el.dataset.v);sheet(`<h2>تعديل ${esc(a.name)}</h2><div class="fgrid"><div class="field"><label for="ae-l">العمر (شهور)</label><input id="ae-l" type="number" value="${a.life}"></div><div class="field"><label for="ae-s">الخردة</label><input id="ae-s" type="number" value="${a.salvage}"></div></div><button class="btn block" style="margin-top:12px" data-a="assetEditSave" data-v="${a.id}">حفظ</button>`)};
A.assetEditSave=async el=>{await dbx(sb.from('assets').update({life_months:Math.max(1,num('ae-l')),salvage:num('ae-s')}).eq('id',el.dataset.v));closeSheet();await refresh();toast('اتحفظ')};
A.assetDispose=async el=>{if(!confirm('استبعاد الأصل من النهارده؟ الإهلاك هيقف.'))return;await dbx(sb.from('assets').update({disposed_at:today()}).eq('id',el.dataset.v));closeSheet();await refresh();toast('اتستبعد')};

// ---------- PARTNERS ----------
const ACCT={draw:'مسحوبات',loan:'دفع عن المصنع (دين له)',loanpay:'سداد له',profit:'نصيبه من الربح',paid:'صرف أرباح',exit:'تخارج',capital:'زيادة رأس مال'};
const pBal=p=>p.acct.reduce((s,e)=>s+e.amt,0);
V.partners=()=>{const show=can('profit')||me().owner;const mains=S.partners.filter(p=>p.kind==='main'&&!p.exited);const tot=mains.reduce((s,p)=>s+p.share,0);
 return head('الشركاء','النسب، والحساب الجاري لكل شريك، والأرباح المحتجزة، والأقساط، والشريك المؤقت',me().owner?'<button class="btn" data-a="partnerEntry">+ حركة على شريك</button><button class="btn sec" data-a="newPartner">+ شريك</button>':'')+
 (mains.length&&Math.abs(tot-100)>0.01?`<div class="alert bad" style="margin-bottom:12px"><span class="dot"></span><div>مجموع نسب الشركاء الأساسيين ${fmt(tot,2)}% مش 100%. <button class="btn ghost sm" data-a="editShares">تعديل النسب</button></div></div>`:'')+
 (S.partners.length?S.partners.map(p=>{const bal=pBal(p);const yr=today().slice(0,4);const ytd=p.acct.filter(e=>e.type==='profit'&&(e.m||'').startsWith(yr)).reduce((s,e)=>s+e.amt,0);return `<div class="card" style="margin-bottom:10px"><div class="between"><div><h2>${esc(p.name)}</h2><div class="small muted">${p.kind==='temp'?`شريك مؤقت · ${{fixedReturn:'عائد ثابت '+p.rate+'% شهريًا',fixedShare:'نسبة ثابتة '+p.rate+'% من الصافي',dilute:'نسبة '+p.rate+'% بالتناسب'}[p.method]||''} · من ${dShort(p.start)} لـ ${p.end?dShort(p.end)+' '+p.end.slice(0,4):'—'}`:'نسبة '+fmt(p.share,2)+'%'} · رأس مال ${show?money(p.capital):'🔒'}</div></div>${p.exited?'<span class="pill">خرج</span>':p.kind==='temp'&&p.end?`<span class="pill acc">باقي ${Math.max(0,daysBetween(today(),p.end))} يوم</span>`:''}</div>
  ${show?`<div class="grid2" style="margin-top:8px">${kpi('الحساب الجاري ('+(bal>=0?'مستحق له':'عليه')+')',`<span class="${bal>=0?'up':'down'}">${money(Math.abs(bal))}</span>`)}${kpi('نصيبه من ربح '+yr,money(ytd),'بيتسوّى آخر السنة')}</div>
  ${p.acct.length?`<details style="margin-top:6px"><summary class="small" style="color:var(--accent)">الحركات (${p.acct.length})</summary><div class="list">${p.acct.slice().reverse().map(e=>`<div class="li"><div class="main"><div class="t small">${ACCT[e.type]||e.type}</div><div class="s">${dShort(e.d)} · ${esc(e.note||'')}</div></div><div class="e ${e.amt>=0?'up':'down'}">${e.amt>=0?'+':''}${fmt(e.amt)}</div></div>`).join('')}</div></details>`:''}
  ${p.plan.length?`<div class="small" style="margin-top:6px">جدول السداد: ${p.plan.map(x=>`<span class="pill ${x.paid?'ok':x.d<today()?'bad':'warn'}">${dShort(x.d)} ${fmt(x.amt)}${x.paid?' ✓':''}</span>`).join(' ')}</div>`:''}
  ${!p.exited&&me().owner?`<div class="row" style="margin-top:8px"><button class="btn sec sm" data-a="partnerEntry" data-v="${p.id}">حركة</button><button class="btn ghost sm" data-a="exitPartner" data-v="${p.id}">تخارج ورد رأس المال</button></div>`:''}`:''}</div>`}).join(''):emptyState('ضيف الشركاء بنسبهم ورأس مال كل واحد.',me().owner?'<button class="btn" data-a="newPartner">+ شريك</button>':''))};
A.partnerEntry=el=>{if(!S.partners.length){toast('ضيف الشركاء الأول');return}const pid=el&&el.dataset&&el.dataset.v;sheet(`<h2>حركة على شريك</h2><div class="fgrid"><div class="field full"><label for="pe-p">الشريك</label><select id="pe-p">${S.partners.filter(p=>!p.exited).map(p=>`<option value="${p.id}" ${p.id===pid?'selected':''}>${esc(p.name)} — ${pBal(p)>=0?'له':'عليه'} ${money(Math.abs(pBal(p)))}</option>`).join('')}</select></div>
 <div class="field full"><label for="pe-k">النوع</label><select id="pe-k" data-chg="peKind"><option value="draw">مسحوبات (تحت حساب الأرباح)</option><option value="paid">صرف من أرباحه المحتجزة</option><option value="loan">دفع عن المصنع (خامة، معدة، مصروف) — دين له</option><option value="loanpay">سداد قسط له</option><option value="capital">زيادة رأس مال</option></select></div>
 <div class="field"><label for="pe-v">المبلغ</label><input id="pe-v" type="number"></div><div class="field" id="pe-t-w"><label for="pe-t">الخزنة</label><select id="pe-t">${trOpts(myTre())}</select></div>
 <div class="field full" id="pe-l-w" hidden><label for="pe-lt">الفلوس راحت فين</label><select id="pe-lt"><option value="t">دخلت خزنة المصنع (الخزنة اللي فوق)</option>${S.suppliers.map(s=>`<option value="s:${s.id}">دفعها لمورد: ${esc(s.name)} (بتقلل حساب المورد)</option>`).join('')}<option value="n">اشترى حاجة على طول (من غير ما تعدي على الخزنة)</option></select></div>
 <div class="field" id="pe-i-w" hidden><label for="pe-i">يترد على كام شهر</label><input id="pe-i" type="number" value="3"></div><div class="field full"><label for="pe-n">البيان</label><input id="pe-n" type="text"></div></div><button class="btn block" style="margin-top:12px" data-a="peSave">تسجيل</button>`)};
A.peKind=el=>{const l=el.value==='loan';document.getElementById('pe-l-w').hidden=!l;document.getElementById('pe-i-w').hidden=!l};
A.peSave=async()=>{if(_busy)return;const k=val('pe-k'),v=num('pe-v');if(v<=0){toast('اكتب المبلغ');return}let t=val('pe-t'),sup_='';if(k==='loan'){const lt=val('pe-lt');if(lt.startsWith('s:')){sup_=lt.slice(2);t=''}else if(lt==='n')t=''}
 _busy=true;try{await rpc('partner_entry',{p:{partner_id:val('pe-p'),type:k,amount:v,treasury_id:t,supplier_id:sup_,inst:k==='loan'?num('pe-i'):0,note:val('pe-n')}});closeSheet();await refresh();toast('اتسجلت الحركة')}finally{_busy=false}};
A.exitPartner=el=>{const p=byId(S.partners,el.dataset.v);const bal=pBal(p);sheet(`<h2>تخارج ${esc(p.name)}</h2><p class="sub">هيسترد رأس ماله ${money(p.capital)} ${bal>=0?'+':'−'} رصيد حسابه الجاري ${money(Math.abs(bal))} = <b>${money(p.capital+bal)}</b></p>${p.kind==='main'?'<div class="alert warn"><span class="dot"></span><div>بعد التخارج عدّل نسب الباقيين علشان مجموعها يبقى 100%.</div></div>':''}<div class="field" style="margin-top:10px"><label for="ex-t2">الصرف من</label><select id="ex-t2">${trOpts(myTre())}</select></div><button class="btn block" style="margin-top:12px" data-a="exitSave" data-v="${p.id}">تأكيد التخارج</button>`)};
A.exitSave=async el=>{await rpc('partner_exit',{p:{partner_id:el.dataset.v,treasury_id:val('ex-t2')}});closeSheet();await refresh();toast('اتقفل حساب الشريك')};
A.newPartner=()=>{const mains=S.partners.filter(p=>p.kind==='main'&&!p.exited);sheet(`<h2>شريك جديد</h2><div class="fgrid"><div class="field"><label for="np-n">الاسم</label><input id="np-n" type="text"></div><div class="field"><label for="np-ph">الموبايل</label><input id="np-ph" type="tel"></div><div class="field"><label for="np-c">رأس المال</label><input id="np-c" type="number" value="0"></div><div class="field"><label for="np-t">رأس المال دخل</label><select id="np-t"><option value="">موجود قبل السيستم (من غير حركة)</option>${trOpts('')}</select></div>
 <div class="field full"><label for="np-k">النوع</label><select id="np-k" data-chg="npKind"><option value="main">شريك أساسي بنسبة</option><option value="fixedReturn">مؤقت · عائد ثابت شهري على المبلغ</option><option value="fixedShare">مؤقت · نسبة ثابتة من الصافي قبل التوزيع</option><option value="dilute">مؤقت · نسبة بتتخصم من نسب الشركاء بالتناسب</option></select></div>
 <div class="field"><label for="np-r">النسبة %</label><input id="np-r" type="number" value="${mains.length?10:100}" data-live="npShares"></div><div class="field" id="np-m-w" hidden><label for="np-m">المدة (شهور)</label><input id="np-m" type="number" value="6"></div></div>
 <div id="np-sh">${npShares()}</div><button class="btn block" style="margin-top:12px" data-a="newPartnerSave">إضافة</button>`)};
function npShares(){const mains=S.partners.filter(p=>p.kind==='main'&&!p.exited);const k=document.getElementById('np-k');if(!mains.length||(k&&k.value!=='main'))return '';const r=num('np-r')||0;
 return `<h3 style="margin-top:12px">نسب الباقيين بعد دخوله ${ti('محسوبة بالتناسب: كل واحد بيتنازل بنفس النسبة من حصته. تقدر تعدّلها')}</h3>${mains.map(p=>`<div class="row" style="flex-wrap:nowrap;margin-bottom:6px"><span style="flex:1">${esc(p.name)} <span class="muted small">(كان ${fmt(p.share,2)}%)</span></span><input type="number" class="inp-sm" id="ns-${p.id}" value="${+(p.share*(100-r)/100).toFixed(2)}" style="width:90px"></div>`).join('')}`}
A.npShares=()=>{const b=document.getElementById('np-sh');if(b)b.innerHTML=npShares()};
A.npKind=el=>{document.getElementById('np-m-w').hidden=el.value==='main';A.npShares()};
A.newPartnerSave=async()=>{const n=val('np-n').trim();if(!n){toast('اكتب الاسم');return}const k=val('np-k');const r=num('np-r');const mains=S.partners.filter(p=>p.kind==='main'&&!p.exited);
 let shares=null;if(k==='main'&&mains.length){shares=mains.map(p=>({id:p.id,share:num('ns-'+p.id)}));const t=shares.reduce((s,x)=>s+x.share,0)+r;if(Math.abs(t-100)>0.05){toast('مجموع النسب '+fmt(t,2)+'% لازم يبقى 100%');return}}
 const p={name:n,phone:val('np-ph'),capital:num('np-c'),treasury_id:val('np-t'),kind:k==='main'?'main':'temp',share:k==='main'?r:0,method:k==='main'?null:k,rate:k==='main'?0:r,start:today(),end:k==='main'?'':addMonth(curMonth(),num('np-m'))+today().slice(7)};if(shares)p.shares=shares;
 await rpc('add_partner',{p});closeSheet();await refresh();toast('اتضاف الشريك')};
A.editShares=()=>{const mains=S.partners.filter(p=>p.kind==='main'&&!p.exited);sheet(`<h2>نسب الشركاء</h2>${mains.map(p=>`<div class="row" style="flex-wrap:nowrap;margin-bottom:6px"><span style="flex:1">${esc(p.name)}</span><input type="number" class="inp-sm" id="es-${p.id}" value="${p.share}" style="width:90px">%</div>`).join('')}<button class="btn block" style="margin-top:12px" data-a="sharesSave">حفظ</button>`)};
A.sharesSave=async()=>{const mains=S.partners.filter(p=>p.kind==='main'&&!p.exited);const shares=mains.map(p=>({id:p.id,share:num('es-'+p.id)}));const t=shares.reduce((s,x)=>s+x.share,0);if(Math.abs(t-100)>0.05){toast('المجموع '+fmt(t,2)+'%، لازم 100%');return}await rpc('set_shares',{p:{shares}});closeSheet();await refresh();toast('اتحفظت النسب')};

// ---------- CLOSING ----------
function closeChecklist(k){const me_=monthEnd(k);const out=[];const cnt=S.counts[k];
 out.push({ok:!!(cnt&&cnt.status==='approved'),hard:true,t:'جرد آخر الشهر معتمد',d:cnt&&cnt.status==='approved'?'اتعتمد · عجز '+money(cnt.loss)+' · زيادة '+money(cnt.gain):'لازم يتعتمد من «المخزن والجرد» قبل الإقفال',go:'stock',tab:'count'});
 const pa=S.att.filter(a=>a.status==='pending'&&inMonth(a.d,k)).length;out.push({ok:!pa,t:'الحضور معتمد',d:pa?pa+' يوم حضور مستني اعتماد':'كله معتمد',go:'staff',tab:'att'});
 const unpaid=S.staff.filter(w=>w.active&&w.type==='monthly'&&!S.payroll.some(p=>p.w===w.id&&p.m===k));out.push({ok:!unpaid.length,t:'مرتبات الشهر',d:unpaid.length?unpaid.length+' موظف لسه ما قبضش مرتب الشهر (مش مشكلة، المرتب محسوب على الشهر)':'اتصرفت',go:'staff'});
 const cu=S.couriers.filter(c=>custodyBal(c.id)>0.5);out.push({ok:!cu.length,t:'عهدة المناديب',d:cu.length?cu.map(c=>c.name+' '+money(custodyBal(c.id))).join(' · '):'مفيش فلوس مع المناديب',go:'cash'});
 const adv=S.staff.reduce((s,w)=>s+advRem(w),0);out.push({ok:true,t:'السلف المفتوحة',d:adv?money(adv)+' لسه ما اتسددتش (بتتخصم من القبض الجاي)':'مفيش',go:'staff',tab:'adv'});
 const outO=S.orders.filter(o=>o.status==='out'&&outMonth(o)===k).length;out.push({ok:!outO,t:'أوردرات مع المندوب',d:outO?outO+' أوردر لسه ما اتأكدش تسليمه':'كله اتسلّم',go:'orders'});
 return out}
V.closing=()=>{if(!can('profit'))return head('الإقفال والتقارير')+`<div class="lock">🔒 الأرباح مخفية عن ${esc(me().name)} (من الصلاحيات)</div>`;
 const tb=tabs([['month','الإقفال الشهري'],['year','السنوي والمقارنة'],['log','سجل الفتح والقفل']],'month');
 if(tb.cur==='log')return head('الإقفال والتقارير')+tb.html+`<div class="card"><div class="list">${(S.closeLog||[]).map(l=>`<div class="li"><div class="main"><div class="t">${l.action==='close'?'🔒 قفل':'🔓 فتح'} ${/Y$/.test(l.month)?'سنة '+l.month.slice(0,4):mName(l.month)}</div><div class="s">${esc(l.by_name||'')} · ${new Date(l.at).toLocaleString('ar-EG')}${l.note?' · '+esc(l.note):''}</div></div></div>`).join('')||'<div class="empty">لسه</div>'}</div></div>`;
 if(tb.cur==='year')return head('الإقفال والتقارير')+tb.html+yearView();
 const keys=recentMonths(6);const k=TAB.closeMonth||curMonth();const m=monthPL(k);const c=S.closings[k];const reserve=TAB.reserve!=null&&TAB.reserveK===k?TAB.reserve:(c?c.reserve:0);const dist=m.closed&&c?c.dist.map(d=>({p:byId(S.partners,d.partner_id)||{name:d.name},amt:d.amount,how:d.how})):distribute(m.net,reserve,k);
 const ck=m.closed?[]:closeChecklist(k);const canClose=ck.every(x=>!x.hard||x.ok);const fixedMissing=(S.settings.fixedCats||[]).filter(cat=>!S.expenses.some(e=>inMonth(e.d,k)&&e.cat===cat&&!e.acc)&&!S.accruals.some(a=>a.m===k&&a.cat===cat));
 const lastAmt=cat=>{const e=S.expenses.filter(x=>x.cat===cat).slice(-1)[0];return e?e.amt:0};
 return head('الإقفال والتقارير','قائمة الدخل، وتوزيع الأرباح، وقفل الشهر')+tb.html+monthTabs(keys,k,'closeMonth')+
 `<div class="card"><div class="between"><h2>قائمة الدخل — ${mName(k)}</h2><span class="pill ${m.closed?'ok':'warn'}">${m.closed?'مقفول · '+esc(c.by||''):'مفتوح'}</span></div><div class="tbl-wrap" style="margin-top:8px"><table>
  <tr><td>المبيعات (بعد الخصومات${m.retDed?' ومرتجعات '+fmt(m.retDed):''})</td><td class="n b">${fmt(m.sales)}</td></tr>
  <tr><td class="muted">مخزون أول المدة${!S.closings[addMonth(k,-1)]?' '+ti('أول شهر في السيستم: قيمة المخزون اللي بدأت بيه من الإعدادات'):''}</td><td class="n">${fmt(m.openInv)}</td></tr><tr><td class="muted">+ مشتريات الشهر</td><td class="n">${fmt(m.purch)}</td></tr><tr><td class="muted">− مخزون آخر المدة ${m.counted?'(بالجرد)':'(من السيستم، الجرد لسه)'}</td><td class="n">${fmt(m.closeInv)}</td></tr>
  <tr class="tot"><td>${m.counted?'تكلفة المبيعات الفعلية':'تكلفة المبيعات من الوصفات (لحد الجرد)'}</td><td class="n">${fmt(m.cogs)}</td></tr>
  ${m.counted?`<tr><td class="muted">المعيارية من الوصفات + تكلفة المرتجعات</td><td class="n">${fmt(m.std+(m.retCost||0))} <span class="small ${m.cogs>m.std+(m.retCost||0)?'down':'up'}">فرق ${fmt(m.cogs-m.std-(m.retCost||0))}</span></td></tr>`:''}
  <tr class="tot"><td>مجمل الربح</td><td class="n">${fmt(m.sales-m.cogs)} <span class="small muted">${pct((m.sales-m.cogs)/(m.sales||1))}</span></td></tr>
  <tr><td>المرتبات واليوميات (بالحضور والغياب والأوفر تايم)</td><td class="n">${fmt(m.payroll)}</td></tr>${Object.entries(m.byCat||{}).map(([cat,v])=>`<tr><td class="muted">${esc(cat)}</td><td class="n">${fmt(v)}</td></tr>`).join('')}<tr><td>إهلاك الأصول</td><td class="n">${fmt(m.dep)}</td></tr>
  <tr class="tot"><td>صافي الربح</td><td class="n ${m.net>=0?'up':'down'}">${fmt(m.net)} <span class="small">${pct(m.net/(m.sales||1))}</span></td></tr></table></div></div>
 ${m.counted&&m.std&&m.cogs>(m.std+(m.retCost||0))*1.03?`<div class="alert bad" style="margin-top:8px"><span class="dot"></span><div>التكلفة الفعلية أعلى من الوصفات بـ ${pct(m.cogs/(m.std+(m.retCost||0))-1)}. راجع الهدر أو الكميات في الوصفات أو فروق الجرد.</div></div>`:''}
 ${m.closed?'':`<div class="card" style="margin-top:12px"><h2>قبل الإقفال</h2><div class="list" style="margin-top:6px">${ck.map(x=>`<div class="li click" data-a="go" data-v="${x.go}"${x.tab?` data-tab="${x.tab}"`:''}><div class="main"><div class="t">${x.ok?'✅':x.hard?'⛔':'⚠️'} ${x.t}</div><div class="s">${esc(x.d)}</div></div></div>`).join('')}</div>
  <h3 style="margin-top:12px">مصروفات ثابتة ما اتدفعتش (تتسجل مستحق على الشهر) ${ti('اكتب المبلغ لو المصروف يخص الشهر ده ولسه ما اتدفعش. سيبه 0 لو مش عليه حاجة')}</h3>
  ${fixedMissing.map(cat=>`<div class="row" style="flex-wrap:nowrap;margin-bottom:6px"><span style="flex:1">${esc(cat)}${lastAmt(cat)?` <span class="muted small">(آخر مرة ${fmt(lastAmt(cat))})</span>`:''}</span><input type="number" class="inp-sm" id="acr-${esc(cat)}" value="0" style="width:100px" data-live="clRecalc"></div>`).join('')||'<p class="small muted">كل المصروفات الثابتة اتسجلت للشهر ده.</p>'}
  <div class="row" style="flex-wrap:nowrap;margin-bottom:6px"><input type="text" id="acr-x-n" placeholder="مستحق تاني (اختياري)" style="flex:1"><input type="number" class="inp-sm" id="acr-x" value="0" style="width:100px" data-live="clRecalc"></div>
  ${S.accruals.filter(a=>a.m===k).map(a=>`<div class="small muted">مسجل: ${esc(a.cat)} ${fmt(a.amt)}</div>`).join('')}</div>`}
 <div class="card" style="margin-top:12px"><h2>توزيع الأرباح</h2>${m.closed?'':`<div class="fgrid" style="margin-top:8px"><div class="field"><label for="cl-res">يتحجز للمصنع (تطوير، معدات، احتياطي)</label><input id="cl-res" type="number" value="${reserve}" data-live="clRes" data-v="${k}"></div><div class="field small muted" style="justify-content:flex-end">الباقي بيتوزع بالنسب. نصيب كل شريك بيتسجل في حسابه الجاري، وهو يسحب أو يأجّل.</div></div>`}
 <div class="tbl-wrap" style="margin-top:8px"><table><tr><th>الشريك</th><th>الطريقة</th><th class="n">النصيب</th></tr>${m.closed&&c&&c.reserve?`<tr><td>محجوز للمصنع</td><td></td><td class="n">${fmt(c.reserve)}</td></tr>`:''}${dist.map(r=>`<tr><td>${esc(r.p.name)}</td><td class="small">${esc(r.how)}</td><td class="n b ${r.amt<0?'down':''}">${fmt(r.amt)}</td></tr>`).join('')||'<tr><td colspan="3" class="empty">ضيف الشركاء من شاشة الشركاء</td></tr>'}</table></div>
 ${m.net<0&&!m.closed?'<p class="small muted" style="margin-top:6px">الشهر خسران: نصيب كل شريك من الخسارة بيتخصم من حسابه، وبيتعوض من أرباح الشهور التانية في تسوية آخر السنة.</p>':''}
 ${me().owner?(m.closed?`<button class="btn sec block" style="margin-top:12px" data-a="reopen" data-v="${k}">🔓 فتح الشهر للتعديل</button>`:`<button class="btn block" style="margin-top:12px" data-a="monthClose" data-v="${k}" ${canClose?'':'disabled'}>${canClose?'🔒 إقفال '+mName(k)+' وتوزيع الأرباح':'⛔ لازم الجرد يتعتمد الأول'}</button>`):''}</div>`};
A.closeMonth=el=>{TAB.closeMonth=el.dataset.v;TAB.reserve=null;render()};
A.clRes=el=>{TAB.reserve=+el.value||0;TAB.reserveK=el.dataset.v;clearTimeout(A._clT);A._clT=setTimeout(()=>{const p=document.activeElement&&document.activeElement.id;render();if(p){const x=document.getElementById(p);if(x){x.focus();try{const l=x.value.length;x.setSelectionRange&&x.type==='text'&&x.setSelectionRange(l,l)}catch(e){}}}},500)};
A.clRecalc=()=>{};
A.monthClose=async el=>{if(_busy)return;const k=el.dataset.v;const accruals=[];(S.settings.fixedCats||[]).forEach(cat=>{const i=document.getElementById('acr-'+cat);if(i&&+i.value>0)accruals.push({cat,amount:+i.value})});if(num('acr-x')>0)accruals.push({cat:val('acr-x-n')||'مستحق',amount:num('acr-x')});
 const reserve=num('cl-res');S.accruals=S.accruals.concat(accruals.map(a=>({m:k,cat:a.cat,amt:a.amount,paid:0})));const m=monthPL(k);const dist=distribute(m.net,reserve,k);
 if(!confirm('إقفال '+mName(k)+' بصافي ربح '+money(m.net)+'؟ بعد الإقفال محدش يقدر يعدّل في الشهر غيرك.')){await refresh();return}
 const pl={sales:+m.sales.toFixed(2),std:+m.std.toFixed(2),retCost:+(m.retCost||0).toFixed(2),retDed:+(m.retDed||0).toFixed(2),cogs:+m.cogs.toFixed(2),payroll:+m.payroll.toFixed(2),otherExp:+m.otherExp.toFixed(2),accr:+m.accr.toFixed(2),dep:+m.dep.toFixed(2),exp:+m.exp.toFixed(2),byCat:m.byCat,waste:0,openInv:+m.openInv.toFixed(2),closeInv:+m.closeInv.toFixed(2),purch:+m.purch.toFixed(2),counted:true,varLoss:m.varLoss,varGain:m.varGain};
 _busy=true;try{await rpc('close_month',{p:{month:k,pl,reserve,accruals,dist:dist.map(r=>({partner_id:r.p.id,name:r.p.name,amount:+r.amt.toFixed(2),how:r.how}))}});TAB.reserve=null;await refresh();toast('اتقفل '+mName(k)+' واتوزعت الأرباح')}finally{_busy=false}};
A.reopen=el=>{const k=el.dataset.v;sheet(`<h2>فتح ${mName(k)}</h2><p class="sub">هيتلغي توزيع الأرباح بتاع الشهر والمستحقات اللي ما اتدفعتش، وتقدر تعدّل وتقفل تاني. الفتح بيتسجل.</p><div class="field"><label for="ro-n">سبب الفتح</label><input id="ro-n" type="text"></div><button class="btn block" style="margin-top:12px" data-a="reopenSave" data-v="${k}">فتح الشهر</button>`)};
A.reopenSave=async el=>{if(!val('ro-n').trim()){toast('اكتب السبب');return}await rpc('reopen_month',{p:{month:el.dataset.v,note:val('ro-n')}});closeSheet();await refresh();toast('اتفتح الشهر')};
function yearView(){const y=TAB.closeYear||today().slice(0,4);const ks=Array.from({length:12},(_,i)=>y+'-'+String(i+1).padStart(2,'0')).filter(k=>k<=curMonth()&&(S.closings[k]||k>=((S.orders[0]||{}).date||curMonth()).slice(0,7)||S.expenses.some(e=>inMonth(e.d,k))));
 const all=ks.map(k=>monthPL(k));const sum=f=>all.reduce((s,m)=>s+(m[f]||0),0);const yc=S.closings[y+'-Y'];const allClosed=ks.length&&ks.every(k=>isClosed(k));
 const pt=S.partners.map(p=>({p,amt:p.acct.filter(e=>e.type==='profit'&&(e.m||'').startsWith(y)).reduce((s,e)=>s+e.amt,0),drawn:p.acct.filter(e=>['draw','paid'].includes(e.type)&&(e.d||'').startsWith(y)).reduce((s,e)=>s-e.amt,0)})).filter(x=>x.amt||x.drawn);
 return `<div class="card"><div class="between"><h2>سنة ${y}</h2>${yc&&yc.status==='closed'?'<span class="pill ok">السنة مقفولة</span>':''}</div>${all.length?`<div class="tbl-wrap" style="margin-top:8px"><table><tr><th>الشهر</th><th class="n">المبيعات</th><th class="n">تكلفة المبيعات</th><th class="n">المصروفات</th><th class="n">الصافي</th><th class="n">الهامش</th><th class="n">التغير</th><th class="n">المخزون</th></tr>
  ${all.map((m,i)=>{const prev=all[i-1];const ch=prev?(m.net-prev.net)/Math.abs(prev.net||1):null;return `<tr><td>${mName(m.k)}${m.open?' *':''}</td><td class="n">${fmt(m.sales)}</td><td class="n">${fmt(m.cogs)}</td><td class="n">${fmt(m.exp)}</td><td class="n b">${fmt(m.net)}</td><td class="n">${pct(m.net/(m.sales||1))}</td><td class="n ${ch>0?'up':ch<0?'down':''}">${ch==null?'—':(ch>0?'▲ ':'▼ ')+pct(Math.abs(ch))}</td><td class="n ${m.closeInv<m.openInv?'down':'up'}">${m.closeInv<m.openInv?'▼':'▲'} ${fmt(m.closeInv)}</td></tr>`}).join('')}
  <tr class="tot"><td>الإجمالي</td><td class="n">${fmt(sum('sales'))}</td><td class="n">${fmt(sum('cogs'))}</td><td class="n">${fmt(sum('exp'))}</td><td class="n">${fmt(sum('net'))}</td><td class="n">${pct(sum('net')/(sum('sales')||1))}</td><td></td><td></td></tr></table></div><p class="small muted">* شهر مفتوح (أرقام تقديرية لحد الإقفال)</p>`:'<div class="empty">لسه مفيش شهور</div>'}</div>
 <div class="card" style="margin-top:12px">${monthsChart()}</div>
 <div class="card" style="margin-top:12px"><h2>تسوية الشركاء لسنة ${y} ${ti('مجموع نصيب كل شريك من ربح وخسارة شهور السنة. الشهر الخسران بيتخصم من أرباح الشهور التانية')}</h2><div class="tbl-wrap" style="margin-top:8px"><table><tr><th>الشريك</th><th class="n">صافي نصيبه من السنة</th><th class="n">سحب خلال السنة</th><th class="n">الحساب الجاري دلوقتي</th></tr>${pt.map(x=>`<tr><td>${esc(x.p.name)}</td><td class="n b">${fmt(x.amt)}</td><td class="n">${fmt(x.drawn)}</td><td class="n ${pBal(x.p)>=0?'up':'down'}">${fmt(pBal(x.p))}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">لسه مفيش شهور مقفولة</td></tr>'}</table></div></div>
 ${me().owner?(yc&&yc.status==='closed'?`<button class="btn sec block" style="margin-top:12px" data-a="reopenYear" data-v="${y}">🔓 فتح السنة</button>`:`<button class="btn block" style="margin-top:12px" data-a="yearClose" data-v="${y}" ${allClosed&&isClosed(y+'-12')?'':'disabled'}>${allClosed&&isClosed(y+'-12')?'🔒 إقفال سنة '+y:'إقفال السنة بعد قفل كل الشهور لحد ديسمبر'}</button>`):''}`}
A.yearClose=async el=>{const y=el.dataset.v;if(!confirm('إقفال سنة '+y+'؟'))return;const ks=Array.from({length:12},(_,i)=>y+'-'+String(i+1).padStart(2,'0')).filter(k=>S.closings[k]);const all=ks.map(k=>monthPL(k));const s=f=>+all.reduce((a,m)=>a+(m[f]||0),0).toFixed(2);
 await rpc('close_year',{p:{year:y,pl:{sales:s('sales'),cogs:s('cogs'),exp:s('exp'),net:s('net')}}});await refresh();toast('اتقفلت السنة')};
A.reopenYear=async el=>{const n=prompt('سبب فتح السنة؟');if(!n)return;await rpc('reopen_year',{p:{year:el.dataset.v,note:n}});await refresh();toast('اتفتحت السنة')};
// ================= CUSTOMER ANALYTICS =================
const salesOrders=()=>S.orders.filter(o=>billable(o));
function lineVal(o,l){return l.q*l.price*(1-(o.custDisc||0)/100)}
const lineCost=l=>l.q*(l.cost||0);
const ago=d=>daysBetween(d,today());
const win=(o,a,b)=>{const x=ago(o.date);return x>=a&&x<b};
function agg(os){const r={n:os.length,val:0,qty:0,cost:0,byP:{}};os.forEach(o=>o.lines.forEach(l=>{const v=lineVal(o,l),c=lineCost(l);r.val+=v;r.qty+=l.q;r.cost+=c;const b=r.byP[l.pid]=r.byP[l.pid]||{val:0,qty:0,cost:0};b.val+=v;b.qty+=l.q;b.cost+=c;b.profit=b.val-b.cost}));r.profit=r.val-r.cost;return r}
function custStats(cid){
 const key='cs:'+cid;if(_memo[key])return _memo[key];
 const os=salesOrders().filter(o=>o.cu===cid).sort((a,b)=>a.date<b.date?-1:1);
 const dates=[...new Set(os.map(o=>o.date))];const gaps=[];for(let i=1;i<dates.length;i++)gaps.push({g:daysBetween(dates[i-1],dates[i]),d:dates[i]});
 const avgGap=avgArr(gaps.filter(x=>ago(x.d)<120).map(x=>x.g));
 const gapR=avgArr(gaps.filter(x=>ago(x.d)<30).map(x=>x.g)),gapP=avgArr(gaps.filter(x=>ago(x.d)>=30&&ago(x.d)<120).map(x=>x.g));
 const last=dates[dates.length-1];const since=last!=null?ago(last):null;
 const idleLimit=avgGap?Math.min(Math.max(2*avgGap,3),S.settings.idleMax):S.settings.idleMax;
 const A30=agg(os.filter(o=>win(o,0,30))),P30=agg(os.filter(o=>win(o,30,60))),P90=agg(os.filter(o=>win(o,30,120))),D90=agg(os.filter(o=>win(o,0,90)));
 const chA=P30.val?(A30.val-P30.val)/P30.val:null;const avg3=P90.val/3;const chB=avg3?(A30.val-avg3)/avg3:null;
 return _memo[key]={c:cust(cid),os,dates,gaps,avgGap,gapR,gapP,last,since,idle:last!=null&&since>idleLimit,idleLimit,A30,P30,P90,D90,chA,chB,first:dates[0]};
}
function signals(st){const th=S.settings.changePct/100;const out=[];const n=st.c.name;if(!st.os.length)return out;
 if(st.idle)out.push(['bad','idle',`${n} بقاله ${st.since} يوم ما طلبش`,`متعوّد يطلب كل ${fmt(st.avgGap||0,1)} يوم تقريبًا · الحد ${fmt(st.idleLimit,0)} يوم · آخر طلب ${dShort(st.last)}`]);
 const dA=st.chA!=null&&st.chA<=-th,dB=st.chB!=null&&st.chB<=-th,uA=st.chA!=null&&st.chA>=th,uB=st.chB!=null&&st.chB>=th;
 if(!st.idle&&(dA||dB))out.push(['warn','down',`${n} قلّل سحبه`,[dA?`آخر 30 يوم ${money(st.A30.val)} مقابل ${money(st.P30.val)} (${pct(st.chA)})`:'',dB?`مقابل متوسط 3 شهور ${money(st.P90.val/3)} (${pct(st.chB)})`:''].filter(Boolean).join(' · ')]);
 if(uA||uB)out.push(['ok','up',`${n} زوّد سحبه`,[uA?`آخر 30 يوم +${pct(st.chA)} عن اللي قبلهم`:'',uB?`+${pct(st.chB)} عن متوسط 3 شهور`:''].filter(Boolean).join(' · ')]);
 if(st.gapR&&st.gapP){if(st.gapR>st.gapP*(1+th))out.push(['warn','slow',`${n} بقى يطلب على فترات أطول`,`كل ${fmt(st.gapR,1)} يوم بدل ${fmt(st.gapP,1)}`]);else if(st.gapR<st.gapP*(1-th))out.push(['ok','fast',`${n} بقى يطلب على فترات أقصر`,`كل ${fmt(st.gapR,1)} يوم بدل ${fmt(st.gapP,1)}`])}
 const pids=new Set([...Object.keys(st.A30.byP),...Object.keys(st.P90.byP)]);const downs=[],ups=[];
 pids.forEach(pid=>{const a=(st.A30.byP[pid]||{}).qty||0,b=((st.P90.byP[pid]||{}).qty||0)/3;const nm=prod(pid).name;
  if(a&&!b&&st.P90.n)out.push(['info','new',`${n} بدأ يطلب ${nm}`,`${fmt(a)} قطعة في آخر 30 يوم، وماكانش بيطلبه قبل كده`]);
  else if(b&&!a&&!st.idle)out.push(['warn','stop',`${n} وقف طلب ${nm}`,`كان بيطلب حوالي ${fmt(b)} قطعة في الشهر`]);
  else if(b){const ch=(a-b)/b;if(ch<=-th)downs.push([nm,ch,a,b]);else if(ch>=th)ups.push([nm,ch,a,b])}});
 if(downs.length&&ups.length)out.push(['info','shift',`${n} قلّل ${downs.map(d=>d[0]).join(' و')} وزوّد ${ups.map(u=>u[0]).join(' و')}`,downs.concat(ups).map(d=>`${d[0]}: ${fmt(d[3])} ← ${fmt(d[2])} قطعة/شهر`).join(' · ')]);
 else if(!st.idle)downs.forEach(d=>out.push(['warn','pdown',`${n} قلّل ${d[0]} ${pct(-d[1])}`,`${fmt(d[2])} قطعة في آخر 30 يوم مقابل متوسط ${fmt(d[3])}`]));
 return out}
const allSignals=()=>S.customers.flatMap(c=>signals(custStats(c.id)).map(s=>[...s,c.id]));
const RANK=[['val','القيمة'],['qty','الكمية'],['profit','الربح']];
const rkVal=(r,k)=>k==='val'?r.val:k==='qty'?r.qty:r.profit;
const rkFmt=(v,k)=>k==='qty'?fmt(v)+' قطعة':money(v);
function rankSeg(){const k=TAB.rankBy||'val';return `<div class="seg" style="max-width:360px">${RANK.filter(([v])=>v!=='profit'||can('cost')).map(([v,t])=>`<button class="${k===v?'on':''}" data-a="rankBy" data-v="${v}">${t}</button>`).join('')}</div>`}
A.rankBy=el=>{TAB.rankBy=el.dataset.v;render()};
function weekBars(os,weeks){weeks=weeks||16;const vals=Array(weeks).fill(0);os.forEach(o=>{const w=Math.floor(ago(o.date)/7);if(w<weeks)vals[weeks-1-w]+=o.lines.reduce((s,l)=>s+lineVal(o,l),0)});
 const W=560,H=170,pad=44,mx=Math.max(1,...vals);const nice=Math.ceil(mx/1000)*1000||1000;const bw=(W-pad-6)/weeks;const y=v=>H-20-(v/nice)*(H-34);
 let g='';[0,.5,1].forEach(f=>{const v=nice*f;g+=`<line x1="${pad}" x2="${W}" y1="${y(v)}" y2="${y(v)}" stroke="var(--line)"/><text x="${pad-6}" y="${y(v)+4}" text-anchor="end">${fmt(v)}</text>`});
 vals.forEach((v,i)=>{const x=pad+3+i*bw;g+=`<rect x="${x}" y="${y(v)}" width="${bw*0.7}" height="${Math.max(0,H-20-y(v))}" rx="3" fill="var(--accent)" opacity="${i>=weeks-4?1:.55}"><title>أسبوع ${weeks-i}: ${fmt(v)} ج</title></rect>`;if(i%4===3||i===weeks-1)g+=`<text x="${x+bw*0.35}" y="${H-5}" text-anchor="middle">${i===weeks-1?'الأسبوع ده':'-'+(weeks-1-i)+'أ'}</text>`});
 return `<svg class="chart" viewBox="0 0 ${W} ${H}">${g}</svg>`}

// ---------- customers screen ----------
const custListOld=V.customers;
V.customers=()=>{const tb=tabs([['dash','لوحة العملاء','أكبر العملاء والمنتجات والتنبيهات'],['compare','مقارنة العملاء','كل العملاء جنب بعض: الأوردرات، القيمة، مدة السحب، والتغيير'],['signals','التنبيهات','عملاء وقفوا أو قللوا أو غيّروا المنتجات'],['list','الحسابات والأسعار','أرصدة العملاء والأسعار الخاصة وحد المديونية']],'dash');
 if(tb.cur==='list'){return custListOld().replace('<div class="kpi" style="margin-bottom:10px">',tb.html+'<div class="kpi" style="margin-bottom:10px">')}
 const k=TAB.rankBy||'val';const sts=S.customers.map(c=>custStats(c.id));const sig=allSignals();
 let body='';
 if(tb.cur==='dash'){
  const tot90=agg(salesOrders().filter(o=>win(o,0,90)));const a30=agg(salesOrders().filter(o=>win(o,0,30)));
  const active=sts.filter(s=>s.since!=null&&s.since<30).length;const idle=sts.filter(s=>s.idle).length;
  const top=sts.map(s=>({s,r:s.D90})).sort((a,b)=>rkVal(b.r,k)-rkVal(a.r,k));const totK=rkVal(tot90,k)||1;
  const pr=Object.entries(tot90.byP).map(([pid,r])=>({p:prod(pid),r,a:(a30.byP[pid]||{qty:0}).qty})).sort((a,b)=>rkVal(b.r,k)-rkVal(a.r,k));
  const notSold=S.products.filter(p=>!a30.byP[p.id]);
  const mxC=Math.max(1,...top.map(t=>rkVal(t.r,k))),mxP=Math.max(1,...pr.map(t=>rkVal(t.r,k)));
  body=`<div class="grid4">${kpi('عملاء نشطين',`${active}<small>من ${S.customers.length}</small>`,'طلبوا في آخر 30 يوم',{go:'customers',tab:'compare',tip:'عدد العملاء اللي طلبوا مرة على الأقل في آخر 30 يوم'})}
   ${kpi('عملاء بقالهم فترة ما طلبوش',`${idle}`,'حسب عادة كل عميل، وبحد أقصى '+S.settings.idleMax+' أيام',{go:'customers',tab:'signals',cls:idle?'down':'up',tip:'العميل بيتحسب متوقف لو عدّى ضعف متوسط المدة بين طلباته أو الحد الأقصى الثابت، أيهم أقل'})}
   ${kpi('متوسط قيمة الأوردر',mv(a30.n?a30.val/a30.n:0),'آخر 30 يوم · '+a30.n+' أوردر',{tip:'إجمالي قيمة الأوردرات ÷ عددها في آخر 30 يوم'})}
   ${kpi('أكبر عميل من المبيعات',top[0]?pct(top[0].r.val/(tot90.val||1)):'—',top[0]?esc(top[0].s.c.name)+' · آخر 90 يوم':'',{tip:'نسبة أكبر عميل من إجمالي المبيعات. لو عالية أوي يبقى فيه خطر الاعتماد على عميل واحد'})}</div>
  <div class="between" style="margin:16px 0 4px"><span class="small muted">الترتيب على أساس (آخر 90 يوم):</span>${rankSeg()}</div>
  <div class="grid2" style="margin-top:8px"><div class="card"><h2 class="sec-title">أكبر المطاعم والكافيهات ${ti('مترتبين حسب اللي سحبوه في آخر 90 يوم. اضغط على أي عميل لتحليله')}</h2><div class="list" style="margin-top:6px">${top.map((t,i)=>`<div class="li click" data-a="custAna" data-v="${t.s.c.id}"><div class="main"><div class="between"><span class="t">${i+1}. ${esc(t.s.c.name)}</span><span class="num small">${rkFmt(rkVal(t.r,k),k)} · ${pct(rkVal(t.r,k)/totK)}</span></div><div class="bar" style="margin-top:5px"><i style="width:${Math.max(2,rkVal(t.r,k)/mxC*100)}%"></i></div><div class="s">${t.r.n} أوردر · بيطلب كل ${t.s.avgGap?fmt(t.s.avgGap,1):'—'} يوم · آخر طلب ${t.s.last?dShort(t.s.last):'—'}${t.s.idle?' · <span class="down">متوقف</span>':''}</div></div></div>`).join('')}</div></div>
   <div class="card"><h2 class="sec-title">أكتر المنتجات مبيعًا ${ti('مترتبة حسب المبيعات في آخر 90 يوم')}</h2><div class="list" style="margin-top:6px">${pr.slice(0,7).map((t,i)=>`<div class="li"><div class="main"><div class="between"><span class="t">${i+1}. ${esc(t.p.name)}</span><span class="num small">${rkFmt(rkVal(t.r,k),k)}</span></div><div class="bar" style="margin-top:5px"><i style="width:${Math.max(2,rkVal(t.r,k)/mxP*100)}%"></i></div></div></div>`).join('')}</div></div></div>
  <div class="grid2" style="margin-top:14px"><div class="card"><h2 class="sec-title">أقل المنتجات حركة ${ti('أقل المنتجات مبيعًا في آخر 90 يوم، واللي ما اتباعتش خالص في آخر 30 يوم')}</h2><div class="list" style="margin-top:6px">${pr.slice(-5).reverse().map(t=>`<div class="li"><div class="main"><div class="t">${esc(t.p.name)}</div><div class="s">${rkFmt(rkVal(t.r,k),k)} في 90 يوم · ${fmt(t.a)} قطعة في آخر 30 يوم</div></div></div>`).join('')}
    ${notSold.length?`<div class="alert warn" style="margin-top:8px"><span class="dot"></span><div><b>ما اتباعتش في آخر 30 يوم:</b> ${notSold.map(p=>esc(p.name)).join('، ')}</div></div>`:''}</div></div>
   <div class="card"><div class="between"><h2>آخر التنبيهات</h2><button class="btn ghost sm" data-a="tab" data-v="signals">الكل (${sig.length}) ↖</button></div><div class="stack" style="margin-top:10px;gap:8px">${sig.slice(0,6).map(sigRow).join('')||'<div class="empty">مفيش تغييرات ملحوظة</div>'}</div></div></div>
  <div class="card" style="margin-top:14px"><h2 class="sec-title">مبيعات العملاء أسبوع بأسبوع ${ti('إجمالي قيمة الأوردرات كل أسبوع لآخر 16 أسبوع. آخر 4 أسابيع بلون أغمق')}</h2>${weekBars(salesOrders())}</div>`}
 if(tb.cur==='compare'){const rows=sts.filter(s=>s.os.length).sort((a,b)=>rkVal(b.D90,k)-rkVal(a.D90,k));const tot=rows.reduce((s,r)=>s+rkVal(r.D90,k),0)||1;
  body=`<div class="between" style="margin-bottom:10px"><span class="small muted">آخر 90 يوم · الترتيب على أساس:</span>${rankSeg()}</div><div class="card"><div class="tbl-wrap"><table><tr><th>العميل</th><th class="n">أوردرات</th><th class="n">القيمة</th><th class="n">الكمية</th>${can('cost')?'<th class="n">الربح</th>':''}<th class="n">متوسط الأوردر</th><th class="n">بيطلب كل ${ti('متوسط عدد الأيام بين كل طلب واللي بعده')}</th><th class="n">آخر طلب</th><th class="n">آخر 30 مقابل اللي قبلهم</th><th class="n">مقابل متوسط 3 شهور</th><th class="n">النسبة</th></tr>
  ${rows.map(s=>{const r=s.D90;const ch=v=>v==null?'—':`<span class="${v>=0?'up':'down'}">${v>=0?'▲':'▼'} ${pct(Math.abs(v))}</span>`;return `<tr class="click" data-a="custAna" data-v="${s.c.id}"><td>${esc(s.c.name)} ${s.idle?'<span class="pill bad">متوقف</span>':''}</td><td class="n">${r.n}</td><td class="n">${fmt(r.val)}</td><td class="n">${fmt(r.qty)}</td>${can('cost')?`<td class="n">${fmt(r.profit)}</td>`:''}<td class="n">${fmt(r.n?r.val/r.n:0)}</td><td class="n">${s.avgGap?fmt(s.avgGap,1)+' يوم':'—'}</td><td class="n">${s.last?dShort(s.last)+' ('+s.since+' يوم)':'—'}</td><td class="n">${ch(s.chA)}</td><td class="n">${ch(s.chB)}</td><td class="n">${pct(rkVal(r,k)/tot)}</td></tr>`}).join('')}</table></div></div>
  <div class="card" style="margin-top:14px"><h2 class="sec-title">مين بيسحب إيه ${ti('كمية كل منتج سحبها كل عميل في آخر 90 يوم')}</h2><div class="tbl-wrap" style="margin-top:8px">${matrix(rows)}</div></div>`}
 if(tb.cur==='signals'){const f=TAB.sigF||'all';const types=[['all','الكل'],['idle','متوقفين'],['down','بيقللوا'],['up','بيزوّدوا'],['product','تغيير المنتجات'],['gap','مدة السحب']];
  const map={idle:['idle'],down:['down','pdown'],up:['up'],product:['new','stop','shift','pdown'],gap:['slow','fast']};const list=f==='all'?sig:sig.filter(s=>map[f].includes(s[1]));
  body=`<div class="tabs">${types.map(([v,t])=>`<button class="tab ${f===v?'on':''}" data-a="sigF" data-v="${v}">${t} (${v==='all'?sig.length:sig.filter(s=>map[v].includes(s[1])).length})</button>`).join('')}</div><div class="stack" style="gap:8px">${list.map(sigRow).join('')||'<div class="empty">مفيش تنبيهات هنا</div>'}</div>
  <p class="note" style="margin-top:12px">العميل بيتحسب «متوقف» لو عدّى ضعف متوسط المدة بين طلباته أو ${S.settings.idleMax} أيام (أيهم أقل). التغيير بيتحسب ملحوظ لو ${S.settings.changePct}% أو أكتر، في المقارنتين: آخر 30 يوم مقابل الـ 30 اللي قبلهم، وآخر 30 يوم مقابل متوسط 3 شهور. النسب دي بتتغير من الإعدادات.</p>`}
 return head('العملاء','داشبورد وتحليل للمطاعم والكافيهات، وحساباتهم وأسعارهم الخاصة','<button class="btn" data-a="editCust" data-v="">+ عميل</button>')+tb.html+body};
A.sigF=el=>{TAB.sigF=el.dataset.v;render()};
function sigRow(s){return `<div class="alert ${s[0]}" data-a="custAna" data-v="${s[4]}" style="cursor:pointer"${tip('اضغط لتحليل العميل')}><span class="dot"></span><div><b>${esc(s[2])}</b><div class="small muted">${esc(s[3])}</div></div></div>`}
function matrix(rows){const pids=S.products.map(p=>p.id).filter(pid=>rows.some(r=>r.D90.byP[pid]));
 return `<table><tr><th>العميل</th>${pids.map(pid=>`<th class="n">${esc(prod(pid).name)}</th>`).join('')}</tr>${rows.map(r=>`<tr><td>${esc(r.c.name)}</td>${pids.map(pid=>{const q=(r.D90.byP[pid]||{}).qty;return `<td class="n ${q?'':'muted'}">${q?fmt(q):'·'}</td>`}).join('')}</tr>`).join('')}</table>`}
A.custAna=el=>{const st=custStats(el.dataset.v);const c=st.c;const sg=signals(st);
 const pids=[...new Set([...Object.keys(st.A30.byP),...Object.keys(st.P90.byP)])];
 sheet(`<div class="between"><h2>تحليل ${esc(c.name)}</h2><div class="row"><button class="btn sec sm" data-a="custDetail" data-v="${c.id}">كشف الحساب</button><button class="btn sec sm" data-a="close">إغلاق</button></div></div><p class="sub">${esc(c.type)} · ${c.pay==='cash'?'كاش':'آجل '+c.days+' يوم'} · عميل من ${st.first?dShort(st.first):'—'}</p>
 ${st.os.length?`<div class="grid2">${kpi('سحب آخر 90 يوم',mv(st.D90.val),fmt(st.D90.qty)+' قطعة · '+st.D90.n+' أوردر')}${kpi('بيطلب كل',`${st.avgGap?fmt(st.avgGap,1):'—'}<small>يوم</small>`,st.gapR&&st.gapP?`آخر 30 يوم: كل ${fmt(st.gapR,1)} · قبلها: كل ${fmt(st.gapP,1)}`:'',{tip:'متوسط عدد الأيام بين كل طلب واللي بعده'})}
 ${kpi('آخر طلب',`${st.since??'—'}<small>يوم</small>`,st.last?dShort(st.last)+(st.idle?' · <span class="down">عدّى الحد ('+fmt(st.idleLimit,0)+' يوم)</span>':''):'',{cls:st.idle?'down':''})}${kpi('آخر 30 يوم',mv(st.A30.val),`${st.chA==null?'':`<span class="${st.chA>=0?'up':'down'}">${pct(st.chA)}</span> عن اللي قبلهم`}${st.chB==null?'':` · <span class="${st.chB>=0?'up':'down'}">${pct(st.chB)}</span> عن متوسط 3 شهور`}`)}</div>
 ${sg.length?`<div class="stack" style="gap:8px;margin-top:12px">${sg.map(s=>`<div class="alert ${s[0]}"><span class="dot"></span><div><b>${esc(s[2])}</b><div class="small muted">${esc(s[3])}</div></div></div>`).join('')}</div>`:''}
 <h3 style="margin-top:14px">السحب أسبوع بأسبوع</h3>${weekBars(st.os)}
 <h3 style="margin-top:12px">المنتجات</h3><div class="tbl-wrap"><table><tr><th>المنتج</th><th class="n">آخر 30 يوم</th><th class="n">متوسط شهري (3 شهور قبلها)</th><th class="n">التغيير</th><th class="n">القيمة 90 يوم</th></tr>${pids.map(pid=>{const a=(st.A30.byP[pid]||{}).qty||0,b=((st.P90.byP[pid]||{}).qty||0)/3;const ch=b?(a-b)/b:null;return `<tr><td>${esc(prod(pid).name)}</td><td class="n">${fmt(a)}</td><td class="n">${fmt(b,0)}</td><td class="n">${ch==null?'<span class="pill acc">جديد</span>':!a?'<span class="pill bad">وقف</span>':`<span class="${ch>=0?'up':'down'}">${ch>=0?'▲':'▼'} ${pct(Math.abs(ch))}</span>`}</td><td class="n">${fmt((st.D90.byP[pid]||{}).val||0)}</td></tr>`}).join('')}</table></div>
 <h3 style="margin-top:12px">مواعيد الطلب</h3><div class="row small" style="gap:4px">${st.gaps.slice(-20).map(g=>`<span class="pill ${g.g>(st.avgGap||0)*1.5?'warn':''}"${tip(dShort(g.d)+': بعد '+g.g+' يوم من اللي قبله')}>${g.g} يوم</span>`).join('')}</div>`:'<div class="empty">العميل ده لسه ما طلبش</div>'}`)};

// ================= FORECAST =================
function addMonth(k,n){let [y,m]=k.split('-').map(Number);m+=n;while(m>12){m-=12;y++}while(m<1){m+=12;y--}return y+'-'+String(m).padStart(2,'0')}
function seasonMult(k){const m=+k.slice(5,7);const ss=S.seasons.filter(s=>s.months.includes(m));return {mult:1+ss.reduce((a,s)=>a+s.pct,0)/100,names:ss.map(s=>s.name+' '+(s.pct>0?'+':'')+s.pct+'%')}}
function forecastModel(){
 const cur=monthPL(curMonth());const hist=S.months.map(m=>({k:m.k,sales:m.sales,cogs:m.cogs,exp:m.exp,waste:m.waste}));
 if(cur.frac>0.5)hist.push({k:curMonth(),sales:cur.sales/cur.frac,est:true});
 const ys=hist.map(h=>h.sales/seasonMult(h.k).mult);const n=ys.length;const xs=ys.map((_,i)=>i);const mx=avgArr(xs),my=avgArr(ys);
 let b=0,d=0;xs.forEach((x,i)=>{b+=(x-mx)*(ys[i]-my);d+=(x-mx)**2});b=d?b/d:0;const a=my-b*mx;
 const res=ys.map((y,i)=>(y-(a+b*i))/(a+b*i));const sd=Math.max(0.06,Math.sqrt(avgArr(res.map(r=>r*r))||0));
 const closed=S.months.slice(-3).filter(m=>m.sales>0);const cogsR=avgArr(closed.map(m=>m.cogs/m.sales))??(cur.sales?cur.cogs/cur.sales:0.45);const wasteR=avgArr(closed.map(m=>(m.waste||0)/m.sales))??0;
 const payroll=S.staff.filter(w=>w.active).reduce((s,w)=>s+(w.type==='monthly'?w.salary:w.salary*26),0);const rent=(S.expenses.filter(e=>e.cat==='إيجار').slice(-1)[0]||{amt:0}).amt;const dep=S.assets.reduce((s,x)=>s+depFor(x,curMonth()),0);
 const varR=0.05;const fixed=Math.max(payroll+rent+dep-avgArr(closed.map(m=>m.sales))*varR*2,avgArr(closed.map(m=>m.exp-m.sales*varR))||0);
 const startK=hist[hist.length-1].est?addMonth(curMonth(),1):addMonth(hist[hist.length-1].k,1);const base0=hist[hist.length-1].est?n:n;
 const fc=[];for(let i=0;i<6;i++){const k=addMonth(startK,i);const se=seasonMult(k);const idx=(hist[hist.length-1].est?n:n)+i;const base=Math.max(0,a+b*idx);const sales=base*se.mult;const w=sd*Math.sqrt(i+1)*1.28;
  const cogs=sales*cogsR,exp=fixed+sales*varR,waste=sales*wasteR;fc.push({k,sales,lo:sales*(1-w),hi:sales*(1+w),cogs,exp,waste,net:sales-cogs-exp-waste,se})}
 return {hist,fc,slope:b,sd,cogsR,wasteR,fixed,varR,payroll,rent,dep,enough:S.months.length>=3}}
function fcChart(M){const all=M.hist.map(h=>({k:h.k,v:h.sales,est:h.est})).concat(M.fc.map(f=>({k:f.k,v:f.sales,lo:f.lo,hi:f.hi,fc:1})));
 const W=620,H=230,pad=46,top=Math.ceil(Math.max(...all.map(x=>x.hi||x.v))/10000)*10000;const bw=(W-pad-6)/all.length;const y=v=>H-24-(v/top)*(H-40);
 let g='';[0,.5,1].forEach(f=>{const v=top*f;g+=`<line x1="${pad}" x2="${W}" y1="${y(v)}" y2="${y(v)}" stroke="var(--line)"/><text x="${pad-6}" y="${y(v)+4}" text-anchor="end">${fmt(v/1000,0)}k</text>`});
 all.forEach((d,i)=>{const x=pad+4+i*bw,w=bw*0.62;g+=`<rect x="${x}" y="${y(d.v)}" width="${w}" height="${H-24-y(d.v)}" rx="3" fill="${d.fc?'var(--accent-soft)':'var(--accent)'}" stroke="${d.fc?'var(--accent)':'none'}" stroke-dasharray="${d.fc?'3 3':''}" opacity="${d.est?.7:1}"><title>${mName(d.k)}: ${fmt(d.v)} ج</title></rect>`;
  if(d.fc)g+=`<line x1="${x+w/2}" x2="${x+w/2}" y1="${y(d.hi)}" y2="${y(d.lo)}" stroke="var(--fg)" stroke-width="1.2"/><line x1="${x+w/2-5}" x2="${x+w/2+5}" y1="${y(d.hi)}" y2="${y(d.hi)}" stroke="var(--fg)"/><line x1="${x+w/2-5}" x2="${x+w/2+5}" y1="${y(d.lo)}" y2="${y(d.lo)}" stroke="var(--fg)"/>`;
  g+=`<text x="${x+w/2}" y="${H-7}" text-anchor="middle">${MONTHS[+d.k.slice(5)-1].slice(0,5)}</text>`});
 return `<svg class="chart" viewBox="0 0 ${W} ${H}">${g}</svg><div class="row small muted" style="gap:14px"><span><span style="color:var(--accent)">■</span> فعلي</span><span>▢ متوقع (الخط = المدى من الأقل للأعلى)</span><span>الشهر الحالي متقدَّر بمعدل الأيام اللي عدّت</span></div>`}
V.forecast=()=>{const M=forecastModel();const tb=tabs([['total','المصنع كله'],['cust','لكل عميل','متوقع كل مطعم وكافيه يسحب قد إيه الشهر الجاي'],['prod','لكل منتج','محتاج تجهّز من كل منتج كام'],['seasons','المواسم','نسبة الزيادة أو النقص في كل موسم']],'total');const P=can('profit');let body='';
 const sum=(n,f)=>M.fc.slice(0,n).reduce((s,x)=>s+x[f],0);
 if(tb.cur==='total')body=`${M.enough?'':'<div class="alert warn"><span class="dot"></span><div>بيانات غير كافية: محتاج 3 شهور مقفولة على الأقل علشان التنبؤ يبقى له معنى.</div></div>'}
  <div class="grid3">${[[1,mName(M.fc[0].k)],[3,'3 شهور ('+MONTHS[+M.fc[0].k.slice(5)-1]+' – '+MONTHS[+M.fc[2].k.slice(5)-1]+')'],[6,'6 شهور ('+MONTHS[+M.fc[0].k.slice(5)-1]+' – '+MONTHS[+M.fc[5].k.slice(5)-1]+')']].map(([n,l])=>kpi('مبيعات '+l,mv(sum(n,'sales')),`من ${fmt(sum(n,'lo'))} لـ ${fmt(sum(n,'hi'))}${P?' · صافي '+fmt(sum(n,'net')):''}`,{hl:n===1,tip:'الرقم المتوقع، والمدى اللي غالبًا هيقع فيه (من الأقل للأعلى)'})).join('')}</div>
  <div class="card" style="margin-top:14px"><h2 class="sec-title">المبيعات: فعلي ومتوقع ${ti('الاتجاه محسوب من آخر الشهور بعد شيل أثر المواسم، وبعدين أثر موسم كل شهر بيتضاف عليه')}</h2>${fcChart(M)}</div>
  <div class="card" style="margin-top:14px"><h2>التوقع شهر بشهر</h2><div class="tbl-wrap" style="margin-top:8px"><table><tr><th>الشهر</th><th class="n">المبيعات المتوقعة</th><th class="n">المدى</th><th class="n">تكلفة الخامات ${ti('المبيعات × متوسط نسبة تكلفة المبيعات لآخر 3 شهور ('+pct(M.cogsR)+')')}</th><th class="n">المصروفات ${ti('ثابتة: مرتبات '+fmt(M.payroll)+' + إيجار '+fmt(M.rent)+' + إهلاك '+fmt(M.dep)+'، ومتغيرة: '+pct(M.varR)+' من المبيعات (غاز، كهربا، توصيل، منظفات)')}</th>${P?'<th class="n">صافي الربح</th>':''}<th>المواسم</th></tr>
  ${M.fc.map(f=>`<tr><td>${mName(f.k)}</td><td class="n b">${fmt(f.sales)}</td><td class="n small">${fmt(f.lo)} – ${fmt(f.hi)}</td><td class="n">${fmt(f.cogs)}</td><td class="n">${fmt(f.exp)}</td>${P?`<td class="n ${f.net<0?'down':'up'}">${fmt(f.net)}</td>`:''}<td class="small">${f.se.names.map(n=>`<span class="pill acc">${esc(n)}</span>`).join(' ')||'<span class="muted">—</span>'}</td></tr>`).join('')}</table></div>
  <p class="note" style="margin-top:10px">الاتجاه الحالي ${M.slope>=0?'صاعد':'نازل'} حوالي ${money(Math.abs(M.slope))} في الشهر (من غير المواسم). المدى بيوسع كل ما الشهر يبعد. ده تقدير يساعدك في التخطيط والشراء، مش رقم مضمون.</p></div>`;
 if(tb.cur==='cust'){const k1=M.fc[0].k;const sm=seasonMult(k1).mult;const rows=S.customers.map(c=>{const st=custStats(c.id);const base=st.D90.val/3,bq=st.D90.qty/3;const tr=st.chB==null?1:Math.min(1.4,Math.max(0.6,1+0.5*st.chB));const f=st.idle?0:1;return {st,val:base*tr*sm*f,qty:bq*tr*sm*f,tr,enough:st.os.length>=3}}).sort((a,b)=>b.val-a.val);
  body=`<div class="card"><p class="sub">متوقع ${mName(k1)}: متوسط سحب آخر 3 شهور × اتجاه العميل × أثر الموسم (${pct(sm-1)})</p><div class="tbl-wrap"><table><tr><th>العميل</th><th class="n">متوسط شهري</th><th class="n">الاتجاه</th><th class="n">متوقع القيمة</th><th class="n">متوقع الكمية</th><th>ملاحظة</th></tr>
  ${rows.map(r=>`<tr class="click" data-a="custAna" data-v="${r.st.c.id}"><td>${esc(r.st.c.name)}</td><td class="n">${fmt(r.st.D90.val/3)}</td><td class="n ${r.tr>=1?'up':'down'}">${r.tr>=1?'▲':'▼'} ${pct(Math.abs(r.tr-1))}</td><td class="n b">${fmt(r.val)}</td><td class="n">${fmt(r.qty)}</td><td class="small">${!r.enough?'<span class="pill">بيانات غير كافية</span>':r.st.idle?'<span class="pill bad">متوقف، مش محسوب</span>':''}</td></tr>`).join('')}
  <tr class="tot"><td>الإجمالي</td><td class="n">${fmt(rows.reduce((s,r)=>s+r.st.D90.val/3,0))}</td><td></td><td class="n">${fmt(rows.reduce((s,r)=>s+r.val,0))}</td><td class="n">${fmt(rows.reduce((s,r)=>s+r.qty,0))}</td><td></td></tr></table></div></div>`}
 if(tb.cur==='prod'){const k1=M.fc[0].k;const sm=seasonMult(k1).mult;const all90=agg(salesOrders().filter(o=>win(o,0,90))),a30=agg(salesOrders().filter(o=>win(o,0,30))),p90=agg(salesOrders().filter(o=>win(o,30,120)));
  const rows=S.products.map(p=>{const q=(all90.byP[p.id]||{qty:0}).qty/3;const a=(a30.byP[p.id]||{qty:0}).qty,b=(p90.byP[p.id]||{qty:0}).qty/3;const tr=b?Math.min(1.4,Math.max(0.6,1+0.5*(a-b)/b)):1;const m=q*tr*sm;return {p,q,tr,m}}).filter(r=>r.q>0).sort((a,b)=>b.m-a.m);
  body=`<div class="card"><p class="sub">جهّز إيه في ${mName(k1)}: متوسط آخر 3 شهور × اتجاه المنتج × أثر الموسم</p><div class="tbl-wrap"><table><tr><th>المنتج</th><th class="n">متوسط شهري</th><th class="n">الاتجاه</th><th class="n">متوقع الشهر</th><th class="n">في الأسبوع</th><th class="n">في اليوم ${ti('متوقع الشهر ÷ 26 يوم شغل')}</th><th class="n">كراتين/أسبوع</th></tr>
  ${rows.map(r=>`<tr><td>${esc(r.p.name)}</td><td class="n">${fmt(r.q,0)}</td><td class="n ${r.tr>=1?'up':'down'}">${r.tr>=1?'▲':'▼'} ${pct(Math.abs(r.tr-1))}</td><td class="n b">${fmt(r.m,0)}</td><td class="n">${fmt(r.m/4.33,0)}</td><td class="n">${fmt(r.m/26,1)}</td><td class="n">${r.p.cat==='cake'?'—':fmt(Math.ceil(r.m/4.33/r.p.ppc))}</td></tr>`).join('')}</table></div>
  <p class="note" style="margin-top:10px">المنتجات اللي ما اتباعتش في آخر 3 شهور مش ظاهرة: ${S.products.filter(p=>!all90.byP[p.id]).map(p=>esc(p.name)).join('، ')||'مفيش'}.</p></div>`}
 if(tb.cur==='seasons')body=`<div class="card"><p class="sub">النسبة بتتضاف على المبيعات المتوقعة في شهور الموسم. لو أكتر من موسم في نفس الشهر، النسب بتتجمع. مواعيد رمضان والعيدين بتتغير كل سنة، فراجع الشهور.</p><div class="tbl-wrap"><table><tr><th>الموسم</th><th>الشهور (أرقام مفصولة بفاصلة)</th><th class="n">التأثير %</th><th></th></tr>
  ${S.seasons.map(s=>`<tr><td><input type="text" id="sn-${s.id}" value="${esc(s.name)}"></td><td><input type="text" id="sm-${s.id}" value="${s.months.join(', ')}" style="max-width:140px;direction:ltr"></td><td class="n"><input class="inp-sm" type="number" id="sp-${s.id}" value="${s.pct}"></td><td><button class="icon-btn" data-a="seasonDel" data-v="${s.id}" aria-label="حذف">×</button></td></tr>`).join('')}</table></div>
  <div class="row" style="margin-top:12px"><button class="btn" data-a="seasonSave">حفظ المواسم</button><button class="btn sec" data-a="seasonAdd">+ موسم</button></div></div>`;
 return head('التنبؤ بالمبيعات والمصروفات','توقع الشهر الجاي و3 و6 شهور على أساس اتجاه المبيعات والمواسم، ولكل عميل ولكل منتج')+tb.html+body};
function readSeasons(){S.seasons.forEach(s=>{const n=document.getElementById('sn-'+s.id);if(!n)return;s.name=n.value;s.months=val('sm-'+s.id).split(/[,،\s]+/).map(Number).filter(x=>x>=1&&x<=12);s.pct=num('sp-'+s.id)})}
A.seasonSave=()=>{readSeasons();render();toast('اتحفظت المواسم واتحسب التنبؤ من جديد')};
A.seasonAdd=()=>{readSeasons();S.seasons.push({id:uid('se'),name:'موسم جديد',months:[],pct:0});render()};
A.seasonDel=el=>{readSeasons();S.seasons=S.seasons.filter(s=>s.id!==el.dataset.v);render()};

const OCC_TPL={xmas:'ميري كريسماس يا {الاسم} 🎄\nكل سنة وانتم طيبين، ونتمنى لكم أيام مليانة فرحة.',ny:'سنة جديدة سعيدة يا {الاسم} ✨\nنتمنى لكم سنة كلها نجاح، ومبسوطين إننا بنكمّلها معاكم.',ramadan:'رمضان كريم يا {الاسم} 🌙\nكل سنة وانتم بخير، ونتمنى لكم شهر مليان خير وبركة.',ramadan10:'تقبّل الله منا ومنكم يا {الاسم} 🌙\nالعشر الأواخر تكون فاتحة خير عليكم.',eid:'عيد سعيد يا {الاسم} 🎉\nكل سنة وانتم طيبين، وينعاد عليكم بالخير والبركة.',spring:'شم نسيم سعيد يا {الاسم} 🌸\nكل سنة وانتم طيبين.',hijri:'كل عام وانتم بخير يا {الاسم} 🌙\nبمناسبة رأس السنة الهجرية.',mawlid:'كل سنة وانتم طيبين يا {الاسم} 🌙\nبمناسبة المولد النبوي الشريف.',bday:'كل سنة وانت طيب يا {الاسم} 🎂\nعيد ميلاد سعيد، ويارب السنة الجاية تكون أحلى.',anniv:'كل سنة وانتم ناجحين يا {الاسم} 🎉\nبمناسبة {المناسبة}، فخورين إننا جزء من نجاحكم.',custom:'تحية خاصة لـ {الاسم} 🤍'};
function personalOcc(){const out=[];const yr=new Date().getFullYear();const nxt=d=>{if(!d)return null;let x=yr+d.slice(4);if(x<today())x=(yr+1)+d.slice(4);return x};
 const add=(e,k,f,name,key)=>{const d=nxt((e.info||{})[f]);if(d&&daysBetween(today(),d)<=60)out.push({id:k+e.id+f,name:name+' — '+e.name,date:d,key,personal:{k,id:e.id}})};
 S.customers.forEach(c=>{add(c,'c',c.kind==='person'?'eventDate':'bday',c.kind==='person'?'المناسبة':'عيد ميلاد '+((c.info||{}).contact||'المسؤول'),c.kind==='person'?'custom':'bday');add(c,'c','opening','ذكرى افتتاح','anniv');add(c,'c','since','ذكرى بداية التعامل','anniv')});
 S.suppliers.forEach(s=>{add(s,'s','bday','عيد ميلاد '+((s.info||{}).contact||''),'bday');add(s,'s','since','ذكرى بداية التعامل','anniv')});
 return out.sort((a,b)=>a.date<b.date?-1:1)}
V.greetings=()=>{const G=TAB.gr;const up=S.occasions.filter(o=>o.date>=daysAddISO(today(),-3)).sort((a,b)=>a.date<b.date?-1:1);const per=personalOcc();
 return head('التهاني والمناسبات','كارت تهنئة باسم كل عميل ومورد، بالمقاسين (مربع وطولي)، ومعاه نص جاهز للواتساب','<button class="btn" data-a="grCustom">+ مناسبة خاصة</button>')+
 `<div class="cols" style="margin-top:0"><div class="card"><h2 class="sec-title">المناسبات الجاية ${ti('التواريخ الهجرية والمتغيرة تقريبية، تقدر تعدّلها')}</h2><div class="list" style="margin-top:6px">${up.map(o=>`<div class="li click" data-a="grPick" data-v="${o.id}"><div class="main"><div class="t">${esc(o.name)}</div><div class="s">${dShort(o.date)} ${o.date.slice(0,4)} · بعد ${Math.max(0,daysBetween(today(),o.date))} يوم</div></div><span class="pill acc">جهّز الكروت</span></div>`).join('')}</div></div>
 <div class="card"><h2 class="sec-title">مناسبات شخصية قريبة ${ti('من دليل العملاء والموردين: أعياد الميلاد، ذكرى الافتتاح، ذكرى بداية التعامل، ومناسبات الأفراد، خلال 60 يوم')}</h2><div class="list" style="margin-top:6px">${per.map(o=>`<div class="li click" data-a="grPersonal" data-v="${o.id}"><div class="main"><div class="t">${esc(o.name)}</div><div class="s">${dShort(o.date)} · بعد ${daysBetween(today(),o.date)} يوم</div></div><span class="pill">كارت</span></div>`).join('')||'<div class="empty">مفيش مناسبات شخصية خلال 60 يوم. ضيف التواريخ من «دليل العملاء والموردين».</div>'}</div></div></div>
 ${G?grCompose(G):''}`};
A.grPick=el=>{const o=S.occasions.find(x=>x.id===el.dataset.v);TAB.gr={occ:o.name,key:o.key,to:'all',brand:'melt',size:'sq',msg:OCC_TPL[o.key]||OCC_TPL.custom,only:null};render();setTimeout(()=>document.getElementById('gr-compose')?.scrollIntoView({behavior:'smooth'}),50)};
A.grPersonal=el=>{const o=personalOcc().find(x=>x.id===el.dataset.v);const e=entity(o.personal.k,o.personal.id);TAB.gr={occ:o.name.split(' — ')[0],key:o.key,to:'one',brand:e.brand||'melt',size:'sq',msg:(OCC_TPL[o.key]||OCC_TPL.custom),only:o.personal};render();setTimeout(()=>document.getElementById('gr-compose')?.scrollIntoView({behavior:'smooth'}),50)};
A.grCustom=()=>{TAB.gr={occ:'مناسبة خاصة',key:'custom',to:'all',brand:'melt',size:'sq',msg:OCC_TPL.custom,only:null,editTitle:true};render()};
let grName=r=>r.k==='c'&&r.e.kind!=='person'?'فريق '+r.e.name:r.e.name;
let grText=(G,r)=>G.msg.replace(/\{الاسم\}/g,grName(r)).replace(/\{المناسبة\}/g,G.occ)+'\nمع تحيات '+brand(G.brand).name;
A.grClose=()=>{TAB.gr=null;render()};
A.grSet=el=>{A.grApply(true);TAB.gr[el.dataset.f]=el.dataset.v;render()};
A.grApply=noRender=>{const G=TAB.gr;if(!G)return;const m=document.getElementById('gr-m');if(m)G.msg=m.value;const t=document.getElementById('gr-t');if(t)G.occ=t.value;if(noRender!==true)render()};
A.grCopy=el=>{const G=TAB.gr;const r=grRecipients(G)[+el.dataset.i];A.copy({dataset:{t:grText(G,r)}})};
A.grDl=el=>{const cv=document.querySelector(`canvas.gcard[data-i="${el.dataset.i}"]`);const r=grRecipients(TAB.gr)[+el.dataset.i];try{cv.toBlob(b=>{const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='تهنئة-'+r.e.name+'.png';document.body.appendChild(a);a.click();a.remove();toast('اتحمّل الكارت')})}catch(e){toast('التحميل مقفول في المعاينة، افتح الملف من جهازك')}};
const _imgCache={};function loadImg(src){return _imgCache[src]=_imgCache[src]||new Promise(res=>{const im=new Image();im.onload=()=>res(im);im.onerror=()=>res(null);im.src=src})}
function wrapLines(ctx,text,maxW){const out=[];text.split('\n').forEach(par=>{let line='';par.split(' ').forEach(w=>{const t=line?line+' '+w:w;if(ctx.measureText(t).width>maxW&&line){out.push(line);line=w}else line=t});out.push(line)});return out}
A.grDl=el=>{const cv=document.querySelector(`canvas.gcard[data-i="${el.dataset.i}"]`);const r=grRecipients(TAB.gr)[+el.dataset.i];cv.toBlob(b=>saveFile('تهنئة-'+(r.person?r.person.name:r.e.name)+'.png',b),'image/png')};
function ensurePeople(){[...S.customers,...S.suppliers].forEach(e=>{e.info=e.info||{};if(!e.info.people){const i=e.info;e.info.people=i.contact?[{name:i.contact,role:i.role||'',mobile:i.mobile||'',whatsapp:i.whatsapp||'',bday:i.bday||'',current:true}]:[]}})}
// greetings per person
function grRecipients(G){ensurePeople();const ex=G.excl||[];const expand=(e,k)=>{const ps=(e.info&&e.info.people)||[];return ps.length?ps.map((p,i)=>({e,k,person:p,key:k+e.id+':'+i})):[{e,k,key:k+e.id}]};
 let list;if(G.only){const e=entity(G.only.k,G.only.id);list=G.only.pi!=null?[{e,k:G.only.k,person:e.info.people[G.only.pi],key:G.only.k+e.id+':'+G.only.pi}]:expand(e,G.only.k)}
 else{const cs=S.customers.filter(c=>!G.brandOnly||(c.brand||'melt')===G.brand).flatMap(e=>expand(e,'c')),ss=S.suppliers.flatMap(e=>expand(e,'s'));list=G.to==='c'?cs:G.to==='s'?ss:cs.concat(ss)}
 return list.filter(r=>!ex.includes(r.key))}
grName=r=>r.person?r.person.name:(r.k==='c'&&r.e.kind!=='person'?'فريق '+r.e.name:r.e.name);
const grSub=r=>r.person?(r.person.role?r.person.role+' — ':'')+r.e.name+(r.person.current===false?' (سابقًا)':''):'';
grText=(G,r)=>G.msg.replace(/\{الاسم\}/g,grName(r)).replace(/\{المناسبة\}/g,G.occ)+'\nمع تحيات '+brand(G.brand).name;
function personalOcc(){ensurePeople();const out=[];const yr=new Date().getFullYear();const nxt=d=>{if(!d)return null;let x=yr+d.slice(4);if(x<today())x=(yr+1)+d.slice(4);return x};const near=d=>d&&daysBetween(today(),d)<=60;
 const all=[...S.customers.map(e=>[e,'c']),...S.suppliers.map(e=>[e,'s'])];
 all.forEach(([e,k])=>{const i=e.info||{};(i.people||[]).forEach((p,pi)=>{const d=nxt(p.bday);if(near(d))out.push({id:k+e.id+'b'+pi,name:'عيد ميلاد '+p.name+' ('+(p.role||'')+' — '+e.name+')',date:d,key:'bday',personal:{k,id:e.id,pi}})});
  if(k==='c'&&e.kind==='person'&&near(nxt(i.eventDate)))out.push({id:k+e.id+'ev',name:'المناسبة — '+e.name,date:nxt(i.eventDate),key:'custom',personal:{k,id:e.id}});
  [['opening','ذكرى افتتاح'],['since','ذكرى بداية التعامل']].forEach(([f,l])=>{const d=nxt(i[f]);if(near(d)&&daysBetween(i[f],d)>300)out.push({id:k+e.id+f,name:l+' — '+e.name,date:d,key:'anniv',personal:{k,id:e.id}})})});
 return out.sort((a,b)=>a.date<b.date?-1:1)}
A.grPersonal=el=>{const o=personalOcc().find(x=>x.id===el.dataset.v);const e=entity(o.personal.k,o.personal.id);TAB.gr={occ:o.name.split(' — ')[0].split(' (')[0],key:o.key,to:'one',brand:e.brand||'melt',size:'sq',msg:(OCC_TPL[o.key]||OCC_TPL.custom),only:o.personal,excl:[]};render();setTimeout(()=>document.getElementById('gr-compose')?.scrollIntoView({behavior:'smooth'}),50)};
A.grExcl=el=>{A.grApply(true);TAB.gr.excl=(TAB.gr.excl||[]).concat([el.dataset.k]);render()};
A.grReset=()=>{A.grApply(true);TAB.gr.excl=[];render()};
function grCompose(G){const rs=grRecipients(G);return `<div class="card" id="gr-compose" style="margin-top:14px"><div class="between"><h2>كروت: ${esc(G.occ)}</h2><button class="btn ghost sm" data-a="grClose">قفل</button></div>
 <div class="fgrid" style="margin-top:10px">${G.editTitle?`<div class="field full"><label for="gr-t">اسم المناسبة</label><input id="gr-t" type="text" value="${esc(G.occ)}" data-chg="grApply"></div>`:''}
 ${G.only?'':`<div class="field"><label>لمين</label><div class="seg"><button class="${G.to==='all'?'on':''}" data-a="grSet" data-f="to" data-v="all">الكل</button><button class="${G.to==='c'?'on':''}" data-a="grSet" data-f="to" data-v="c">العملاء</button><button class="${G.to==='s'?'on':''}" data-a="grSet" data-f="to" data-v="s">الموردين</button></div></div>`}
 <div class="field"><label>المقاس</label><div class="seg"><button class="${G.size==='sq'?'on':''}" data-a="grSet" data-f="size" data-v="sq">مربع (شات)</button><button class="${G.size==='st'?'on':''}" data-a="grSet" data-f="size" data-v="st">طولي (حالة)</button></div></div>
 <div class="field"><label>البراند</label><div class="seg">${S.brands.map(b=>`<button class="${G.brand===b.id?'on':''}" data-a="grSet" data-f="brand" data-v="${b.id}">${esc(b.name)}</button>`).join('')}</div></div>
 <div class="field full"><label for="gr-m">نص الرسالة ({الاسم} بيتبدل باسم كل شخص)</label><textarea id="gr-m" rows="3" data-chg="grApply">${esc(G.msg)}</textarea></div></div>
 <p class="small muted" style="margin-top:8px">${rs.length} كارت، لكل شخص في كل مكان كارت باسمه وصفته (المالك والمدير ومسؤول المشتريات...).${(G.excl||[]).length?` <button class="btn ghost sm" data-a="grReset">رجّع المستبعدين (${G.excl.length})</button>`:''}</p>
 <div class="grid3" style="margin-top:10px">${rs.map((r,i)=>{const ph=(r.person&&(r.person.whatsapp||r.person.mobile))||(r.e.info||{}).whatsapp||(r.e.info||{}).mobile||r.e.phone||'';return `<div class="card flat" style="padding:10px"><canvas class="gcard" data-i="${i}" style="width:100%;height:auto;border-radius:10px;display:block;border:1px solid var(--line)"></canvas>
  <div class="small b" style="margin-top:8px">${esc(grName(r))}</div><div class="small muted">${esc(grSub(r)||r.e.name)}</div><div class="small muted num" style="direction:ltr;text-align:right">${esc(ph)||'مفيش رقم'}</div>
  <div class="row" style="margin-top:6px"><button class="btn sm" data-a="grDl" data-i="${i}">حفظ الصورة</button><button class="btn sec sm" data-a="grCopy" data-i="${i}">نسخ النص</button><button class="btn ghost sm" data-a="grExcl" data-k="${r.key}">استبعاد</button></div></div>`}).join('')}</div></div>`}
async function drawCards(){const G=TAB.gr;if(!G)return;const cvs=document.querySelectorAll('canvas.gcard');if(!cvs.length)return;const B=brand(G.brand);const K=Object.assign({ink:'#3a2416',acc:'#b8894a',acc2:'#94692c',line:'#e1c9a0',bg1:'#fffaf3',bg2:'#f3e6d3'},B.id==='b2'?{ink:'#480903',acc:'#CE793A',acc2:'#B64B12',bg1:'#fbf5e8',bg2:'#E5D1A4'}:{},Object.fromEntries(Object.entries(B.c||{}).filter(([k,v])=>v)));const logo=B.logo?await loadImg(B.logo):null;
 try{await Promise.all([document.fonts.load('700 80px "El Messiri"'),document.fonts.load('500 40px "IBM Plex Sans Arabic"')])}catch(e){}
 const rs=grRecipients(G);cvs.forEach(cv=>{const r=rs[+cv.dataset.i];if(!r)return;const st=G.size==='st';const W=1080,H=st?1920:1080;cv.width=W;cv.height=H;const x=cv.getContext('2d');
  const g=x.createLinearGradient(0,0,0,H);g.addColorStop(0,K.bg1);g.addColorStop(1,K.bg2);x.fillStyle=g;x.fillRect(0,0,W,H);
  x.strokeStyle=K.acc;x.lineWidth=4;x.strokeRect(36,36,W-72,H-72);x.lineWidth=1.5;x.strokeRect(52,52,W-104,H-104);
  [[70,70],[W-70,70],[70,H-70],[W-70,H-70]].forEach(([a,b])=>{x.save();x.translate(a,b);x.rotate(Math.PI/4);x.fillStyle=K.acc;x.fillRect(-9,-9,18,18);x.restore()});
  let y=st?200:100;
  if(logo){const lw=st?520:380,lh=lw*logo.height/logo.width;x.drawImage(logo,(W-lw)/2,y,lw,lh);y+=lh+36}else{x.fillStyle=K.ink;x.font='700 76px "El Messiri",serif';x.textAlign='center';x.fillText(B.name,W/2,y+70);y+=130}
  x.direction='rtl';x.textAlign='center';x.fillStyle=K.ink;x.font=`700 ${st?104:80}px "El Messiri",serif`;x.fillText(G.occ,W/2,y+66);y+=st?140:108;
  x.strokeStyle=K.acc;x.lineWidth=2;x.beginPath();x.moveTo(W/2-160,y);x.lineTo(W/2+160,y);x.stroke();x.fillStyle=K.acc;x.beginPath();x.arc(W/2,y,7,0,7);x.fill();y+=st?96:66;
  const sub=grSub(r);if(sub){x.fillStyle=K.acc2;x.font=`600 ${st?40:32}px "IBM Plex Sans Arabic",sans-serif`;x.fillText('إلى: '+grName(r)+' — '+sub,W/2,y);y+=st?90:66}
  x.fillStyle='#3a2416';x.font=`500 ${st?54:42}px "IBM Plex Sans Arabic",sans-serif`;wrapLines(x,grText(G,r).split('\nمع تحيات')[0],W-220).forEach(l=>{x.fillText(l,W/2,y);y+=st?84:64});
  x.fillStyle=K.acc2;x.font=`600 ${st?44:34}px "IBM Plex Sans Arabic",sans-serif`;x.fillText('مع تحيات '+B.name,W/2,H-(st?250:170));
  if(B.tagline){x.direction='ltr';x.font=`italic 400 ${st?36:28}px Georgia,serif`;x.fillStyle=K.acc2;x.fillText(B.tagline,W/2,H-(st?180:116))}
  x.direction='ltr';x.font='400 26px "IBM Plex Mono",monospace';x.fillStyle='#8a7560';x.fillText(S.settings.phones||'',W/2,H-(st?120:76))})}

// ================= PARTNER SHARE CALCULATOR =================
function pcBody(){const P=TAB.pc=TAB.pc||{p:10,mode:'new'};const p=P.p/100;const ms=S.months.slice(-6).map(m=>{const net=m.sales-m.cogs-m.exp-m.waste;const temps=distribute(net).filter(r=>r.p.kind==='temp').reduce((s,r)=>s+r.amt,0);return {k:m.k,net,pool:net-temps}});
 const A_=ms.map(m=>m.net*p),B_=ms.map(m=>m.pool*p);const mn=a=>Math.min(...a),mxx=a=>Math.max(...a),av=a=>avgArr(a);let fc=[];try{fc=forecastModel().fc.slice(0,3)}catch(e){}
 const fcA=fc.map(f=>f.net*p);const fcB=fc.map(f=>(f.net-distribute(f.net).filter(r=>r.p.kind==='temp').reduce((s,r)=>s+r.amt,0))*p);const main=S.partners.filter(x=>x.kind==='main');const avgPool=av(ms.map(m=>m.pool));
 return `<div class="grid4">${kpi('أقل شهر',mv(mn(B_)),'من الصافي كله: '+fmt(mn(A_)),{tip:'نصيبه من الصافي بعد الشركاء المؤقتين، وتحته من الصافي كله'})}${kpi('المتوسط الشهري',mv(av(B_)),'من الصافي كله: '+fmt(av(A_)),{hl:1})}${kpi('أعلى شهر',mv(mxx(B_)),'من الصافي كله: '+fmt(mxx(A_)))}${kpi('المتوقع في السنة',mv(av(B_)*12),'المتوسط × 12 شهر')}</div>
 <div class="tbl-wrap" style="margin-top:12px"><table><tr><th>الشهر</th><th class="n">صافي الربح</th><th class="n">بعد الشركاء المؤقتين</th><th class="n">${P.p}% من الصافي كله</th><th class="n">${P.p}% بعد المؤقتين</th></tr>
 ${ms.map((m,i)=>`<tr><td>${mName(m.k)}</td><td class="n">${fmt(m.net)}</td><td class="n">${fmt(m.pool)}</td><td class="n">${fmt(A_[i])}</td><td class="n b">${fmt(B_[i])}</td></tr>`).join('')}
 ${fc.map((f,i)=>`<tr style="background:var(--accent-soft)"><td>${mName(f.k)} <span class="tag-mini">متوقع</span></td><td class="n">${fmt(f.net)}</td><td class="n">${fmt(fcB[i]/p||0)}</td><td class="n">${fmt(fcA[i])}</td><td class="n b">${fmt(fcB[i])}</td></tr>`).join('')}</table></div>
 ${P.mode==='new'?`<h3 style="margin-top:14px">لو دخل شريك جديد بـ ${P.p}%: نسب الباقيين بتقل بالتناسب</h3><div class="tbl-wrap"><table><tr><th>الشريك</th><th class="n">النسبة الحالية</th><th class="n">النسبة الجديدة</th><th class="n">متوسط شهري قبل</th><th class="n">متوسط شهري بعد</th><th class="n">الفرق</th></tr>
 ${main.map(x=>{const nw=x.share*(1-p);return `<tr><td>${esc(x.name)}</td><td class="n">${fmt(x.share,2)}%</td><td class="n b">${fmt(nw,2)}%</td><td class="n">${fmt(avgPool*x.share/100)}</td><td class="n">${fmt(avgPool*nw/100)}</td><td class="n down">-${fmt(avgPool*(x.share-nw)/100)}</td></tr>`}).join('')}
 <tr class="tot"><td>الشريك الجديد</td><td class="n">—</td><td class="n">${P.p}%</td><td class="n">—</td><td class="n">${fmt(avgPool*p)}</td><td></td></tr></table></div>`:''}
 <p class="note" style="margin-top:10px">الأرقام مبنية على آخر ${ms.length} شهور مقفولة والتوقع من شاشة التنبؤ. ده تقدير يساعد الشريك يقرر، مش مبلغ مضمون.</p>`}
const partnersOld=V.partners;
V.partners=()=>{const base=partnersOld();if(!can('profit'))return base;const P=TAB.pc=TAB.pc||{p:10,mode:'new'};
 const calc=`<div class="card" style="margin-bottom:14px"><h2 class="sec-title">حاسبة نسبة الشريك ${ti('اكتب النسبة، والسيستم يقولك الشريك هيطلع له كام بناءً على الشهور اللي فاتت والتوقع')}</h2>
 <div class="fgrid" style="margin-top:10px"><div class="field"><label for="pc-p">النسبة %</label><input id="pc-p" type="number" value="${P.p}" data-live="pcCalc"></div><div class="field"><label>الحالة</label><div class="seg"><button class="${P.mode==='new'?'on':''}" data-a="pcMode" data-v="new">شريك جديد (الباقيين يقلوا)</button><button class="${P.mode==='old'?'on':''}" data-a="pcMode" data-v="old">نسبة شريك موجود</button></div></div></div>
 <div id="pc-res" style="margin-top:12px">${pcBody()}</div></div>`;
 return base.replace('<div class="card" style="margin-bottom:10px">',calc+'<div class="card" style="margin-bottom:10px">')};
A.pcCalc=()=>{TAB.pc.p=Math.max(0,Math.min(100,num('pc-p')));document.getElementById('pc-res').innerHTML=pcBody();applyGloss(document.getElementById('pc-res'))};
